const CHAPTERS=[{"title": "01 京城有家", "place": "东京·槐树巷", "art": "a01"}, {"title": "02 岳庙香火", "place": "东京·岳庙", "art": "a02"}, {"title": "03 故友设宴", "place": "东京·陆宅", "art": "a03"}, {"title": "04 买刀与请帖", "place": "东京·禁军街", "art": "a04"}, {"title": "05 狱中一纸", "place": "开封府·牢狱", "art": "a05"}, {"title": "06 城外分袂", "place": "东京·长亭", "art": "a06"}, {"title": "07 野猪林", "place": "东京北路·密林", "art": "a07"}, {"title": "08 沧州门内", "place": "沧州·牢城营", "art": "a08"}, {"title": "09 北地草场", "place": "沧州·草料场", "art": "a09"}, {"title": "10 雪里家书", "place": "沧州·小屋", "art": "a10"}, {"title": "11 风雪压门", "place": "沧州·山神庙", "art": "a11"}, {"title": "12 雪中断旧", "place": "沧州·火场外", "art": "a12"}, {"title": "13 柴庄回音", "place": "横海郡·柴庄", "art": "a13"}, {"title": "14 水泊门槛", "place": "梁山泊·朱贵酒店", "art": "a14"}, {"title": "15 投名状", "place": "梁山泊·山下官道", "art": "a15"}, {"title": "16 英雄相逢", "place": "梁山泊·山道", "art": "a16"}, {"title": "17 容不下的人", "place": "梁山泊·聚义厅", "art": "a17"}, {"title": "18 山寨粮账", "place": "梁山泊·仓廒", "art": "a18"}, {"title": "19 旧人来山", "place": "梁山泊·南寨门", "art": "a19"}, {"title": "20 渡口接应", "place": "梁山泊·南岸芦荡", "art": "a20"}, {"title": "21 英雄排座", "place": "梁山泊·聚义厅", "art": "a21"}, {"title": "22 阵前救人", "place": "梁山泊·北岸", "art": "a22"}, {"title": "23 一纸招安", "place": "梁山泊·聚义厅", "art": "a23"}, {"title": "24 空着的主位", "place": "梁山泊·祭堂", "art": "a24"}, {"title": "25 两条归路", "place": "梁山泊·议事台", "art": "a25"}, {"title": "26 名册上的人", "place": "途中·临时营地", "art": "a26"}, {"title": "27 江南风雨", "place": "途中·水乡渡口", "art": "a27"}, {"title": "28 不留一个", "place": "途中·石桥", "art": "a28"}, {"title": "29 旧案回声", "place": "途中·州县", "art": "a29"}, {"title": "30 暮年之前", "place": "江畔·旅舍", "art": "a30"}, {"title": "31 归舟有灯", "place": "江畔·候船处", "art": "a31"}, {"title": "32 风雪尽处", "place": "归程·落脚之地", "art": "a32"}];
const NODES=[{"ch": 0, "title": "枪穗上的线头", "text": "天还没亮，你已在院中练完一趟枪。贞娘披衣出来，见枪穗磨散，便拿了针线坐在井旁。你是八十万禁军枪棒教头，领的俸禄算不上丰厚，总够一家吃穿。街坊见你都会拱手，你也习惯把声音放低，觉得人只要守规矩，日子便能长久。她问今日能否早些回来，岳庙有香会，父亲也想吃你带的热炊饼。营门点卯的梆子从街口传来，桌上的早饭还冒着白气。", "options": [{"label": "陪她吃完早饭再走", "effects": {"家": 2, "钱": -1}, "feedback": "你把枪靠回墙边，替她剥开一个鸡蛋。迟到须托同僚代点，花去一点人情钱；她记住的却是你坐下来的这一刻。"}, {"label": "先去营中，把休沐换出来", "effects": {"势": 2, "家": -1}, "feedback": "你在袖口留了张字条便出门。值房答应给你半日休沐，贞娘独自收了碗，也没有责怪，只把未缝完的枪穗放在枕边。"}]}, {"ch": 0, "title": "营门一声教头", "text": "校场上有人拿你的长枪取笑，说太平年月只消会陪上官看球，何必日日练得手掌起茧。你手下有个新兵，家里借债送他入伍，握枪时总在发抖。操演簿上写着人数齐整，真能上阵的却没有几个。掌案催你签字，签了便早散，若逐个重验，就会得罪替人吃空额的管营。你望见新兵虎口裂开的血口，忽然想起自己初入军时，也曾等过教头一句公道话。", "options": [{"label": "重验枪阵，护下那个新兵", "effects": {"义": 2, "势": -1}, "feedback": "你把枪一支支验过，又替新兵包好手掌。操演拖到日上三竿，掌案脸色难看，队伍里却第一次有人敢正眼看你。"}, {"label": "先签簿，私下补教", "effects": {"势": 2, "证": -1}, "feedback": "簿子照旧盖了印，你留下几名新兵练到午后。他们学到了真本事，空额的纸证却从此也有了你的名字。"}]}, {"ch": 0, "title": "市桥一袋银钱", "text": "回家经过州桥，一个做旧衣的邻人拦住你，问要不要替人镇一场欠账。只须穿着教头袍往门口一站，酬银便够抵半月俸禄。他说欠钱的人确实赖账，却不肯让你看借契。桥下船夫正为一斗米讨价还价，城中每一个看似体面的称呼，背后都能换出价钱。你想起家中要修漏雨的屋顶，也想起自己从未问过，这身袍子离开校场后，究竟能给谁作担保。", "options": [{"label": "看清借契才肯出面", "effects": {"证": 2, "钱": -1}, "feedback": "你陪他去找债主，发现利息早已滚过本金。生意没有谈成，你倒买下一份旧契作样本，知道了纸上藏人的办法。"}, {"label": "谢绝，省下这趟人情", "effects": {"家": 1, "义": 1}, "feedback": "你没有借官身挣钱，转头买了两张热饼回家。屋顶仍得等下月修，贞娘却说，少欠一笔人情，也是攒下了家底。"}]}, {"ch": 0, "title": "门闩与后路", "text": "夜里下了一阵急雨，屋顶漏水，你端盆去接。贞娘把积蓄摊在桌上，问要不要送一些给城外父亲保管，省得家中遭火遭盗便一无所有。你笑她想得远，手却停在银袋上。她并非怕穷，只说家不是一间屋子，人在，才有以后。窗纸上映着你们并坐的影子，远处禁中鼓声平稳。那时你还不知道，后来许多路，要从这样一个平常雨夜里借出第一步。", "options": [{"label": "分银藏在岳父处", "effects": {"钱": -2, "路": 2, "藏银": 1}, "feedback": "你写好数目，请她明日带走。可用银钱少了，城外却多了一处不必惊动官府也能借宿的门。"}, {"label": "留银修屋，眼下安稳要紧", "effects": {"家": 2, "势": 1}, "feedback": "你请匠人换掉坏瓦，又修好门闩。家里终于不漏雨，你也愈发相信，只要把眼前的缝补牢，风雨便进不来。"}]}, {"ch": 1, "title": "帘外一声惊呼", "text": "香会人挤得石阶都看不见，卖糖人的竹签从人肩间伸出来。你原想陪贞娘看一会儿，却被一阵喝彩引到菜园边。一个和尚正将垂杨柳连根拔起，泥土抖落，众人齐声叫好。你看出他肩背用力的门道，正想上前请教，随你来的使女却跌跌撞撞跑到眼前，说娘子被人堵在庙后，不许她出来。刚结识的热闹忽然远去，你听见自己刀鞘撞上石栏的声音。", "options": [{"label": "立刻随使女进庙", "effects": {"家": 2, "忍": -1}, "feedback": "你拨开人群往里走，手已经握住刀柄。和尚见你神色变了，也放下酒碗，跟在后面，没有先问你要对付的是谁。"}, {"label": "先让使女去叫岳父与香客作证", "effects": {"证": 2, "家": -1}, "feedback": "你一边往庙后赶，一边把见证人安排出去。多耽搁的几息像针扎着心口，至少这场事不会只剩两张嘴各说各话。"}]}, {"ch": 1, "title": "那张熟悉的脸", "text": "贞娘背靠殿柱，衣袖被人攥着，见你来才把憋住的眼泪咽下去。你一把扭住那人的手腕，拳头举到半空，看清了他的脸：是高太尉的衙内。围观者本来要叫好，认出他后，连喘气都轻了。他反问你何必动怒，说不过同娘子说几句话。你知道这一拳打下去会惊动谁，也看见贞娘指节发白，仍在竭力让自己的声音不发抖。", "options": [{"label": "当众喝斥，先护她离开", "effects": {"家": 2, "势": -2}, "feedback": "你把她挡在身后，清清楚楚说她是你的妻。衙内松了手，眼神却从羞恼变成了记恨，身旁随从把你的姓名记了下来。"}, {"label": "压住拳头，叫他赔礼", "effects": {"忍": 2, "势": 1}, "feedback": "你没有打下去，只逼他退开一步。他嬉笑着敷衍一句，围观者散开了。贞娘握住你的手，掌心凉得像井水。"}]}, {"ch": 1, "title": "和尚替谁出头", "text": "走出庙门，鲁智深扯开僧袍，问那厮在哪。他说认得太尉也好，不认得也好，欺辱良家女子的拳头都该一样挨。你第一次见有人说起权势，像说起挡路的一块石头。你却还有官身、有房舍、有年迈岳父，不能只把今日痛快算作全部日子。鲁智深见你沉默，便不再催，只问一句：若下回他还来，你准备让谁挡在你娘子前头？", "options": [{"label": "同鲁智深约下互通消息", "effects": {"义": 2, "鲁约": 1}, "feedback": "你把家门和岳父住处说给他听。他记得很牢，临别还嘱咐使女，遇事别只找教头，来菜园喊洒家也一样。"}, {"label": "道谢，暂不牵他入局", "effects": {"忍": 2, "势": 1}, "feedback": "你向他作揖，说不愿连累出家人。他叹一声，把半壶酒塞给你，仍说有难就来，交情不必等你请才算数。"}]}, {"ch": 1, "title": "她想听的那句话", "text": "回到家中，贞娘洗了三遍被攥过的袖口。你说衙内不过一时胡闹，过几日兴许就忘了，她没有接话，只问以后出门是不是都该有人陪。你想起官场里惯用的宽慰，一句也说不出口。桌上的香灰还没有倒掉，原本求一家平安的红纸压在杯底。她需要的不是你替别人解释，也不是你立刻许下做不到的狠话，而是一条遇见危险时能照着走的路。", "options": [{"label": "约好暗号与求援处", "effects": {"家": 2, "暗号": 1}, "feedback": "你们定下两种口信，又把岳父、菜园、城外住处一一写在纸上。她终于肯坐下吃饭，眼里的不安却没有因此凭空消失。"}, {"label": "承诺以后亲自接送", "effects": {"家": 2, "钱": -1}, "feedback": "你调开几次值班，亲自陪她出门。这能护住眼前几日，却也让上官发现，你开始为家事推辞原本从不推辞的差遣。"}]}, {"ch": 2, "title": "半扇关着的门", "text": "陆谦送来酒帖，说多年交情，不该因一点烦心事疏远。你们早年一同落魄，曾挤在同一间漏风的客店，他知道你爱吃哪样菜，也知道你把旧情看得比场面重。酒帖上却特意写了请你独来，免得席间不自在。贞娘把帖子翻来覆去看了两遍，想说什么，又怕被你听成疑心故友。院门外有陌生脚步停过片刻，你抬头时，只见一角衣摆转进巷口。", "options": [{"label": "赴宴但留下去向与时辰", "effects": {"证": 2, "家": 1}, "feedback": "你在桌上写清地址，约定二更未回便去找鲁智深。陆谦仍是故友，你却不再把交情当成无需核验的通行牌。"}, {"label": "照旧赴宴，不让疑心毁交情", "effects": {"势": 2, "忍": 1}, "feedback": "你把帖子收进袖中，叫家里不必等饭。陆谦亲自迎到门口，笑容像从前一样亲切，门却在你身后关得很快。"}]}, {"ch": 2, "title": "杯底没有旧情", "text": "席上只有你和陆谦两人。他先谈你们年轻时的穷困，又说如今各有前程，凡事别太倔。你问他为何屡屡提起衙内，他便用酒杯遮住嘴，夸贞娘贤惠。窗外有小厮来报了两次话，他都出去答应，回来仍劝你再饮一盏。菜逐渐凉了，你发现自己从头到尾没有吃到几口，光在听他替另一个人把不可告人的念头，改说成世道如此、人情如此。", "options": [{"label": "借口更衣，查看院外动静", "effects": {"证": 2, "忍": -1}, "feedback": "你走到廊下，听见小厮说林娘子已请到楼上。酒意顿时散了，你没有立刻砸门，先记住楼的位置与守门人的面孔。"}, {"label": "逼陆谦当面说清", "effects": {"势": -1, "义": 2}, "feedback": "你按住酒壶，不许他再绕话。他脸上的笑一点点褪下去，终于说有人看中了你娘子，劝你识相，字字都像旧交情裂开的声音。"}]}, {"ch": 2, "title": "楼上那把闩", "text": "使女在陆宅楼下急得哭，贞娘被人骗来，说你醉得不能回家。她进屋才见到衙内，立刻退回窗边，拿簪子抵住自己，不让人近身。你撞开楼门时，满屋人都在说误会，仿佛只要谁也没死，一切便能被抹平。衙内从侧梯逃走，陆谦站在门外，既不拦也不敢看你。贞娘额头碰青了一块，第一句话却是问你有没有喝下什么不干净的酒。", "options": [{"label": "先接她回家，留下使女作证", "effects": {"家": 2, "证": 1}, "feedback": "你把外衣披在她身上，不让旁人再围着看。使女记下谁来传话，岳父随后赶到，终于听全了这场设局的来龙去脉。"}, {"label": "当场砸毁酒席，逼陆谦认账", "effects": {"义": 2, "势": -2}, "feedback": "碗盘碎了满地，你把陆谦推到墙边，逼他在众人面前认下骗妻赴宴。他认了，转眼却又盘算谁能替他挡下你的怒火。"}]}, {"ch": 2, "title": "旧友两个字", "text": "夜深后，陆谦又差人递来一封赔罪信，信里不提衙内，只说自己酒后失言。你少年时还替他抄过兵书，连他母亲的丧事也出过银钱。贞娘没有叫你报仇，她把断掉的银簪放进匣中，说有些门既然关过一次，就不该再拿自己去试能不能重新打开。你把信放在灯下，纸上有熟悉的字，意思却像从未认识过的人写的。", "options": [{"label": "保存信与断簪，断绝往来", "effects": {"证": 2, "断陆": 1}, "feedback": "你没有烧信，把它同使女的证言放在一起。从此陆谦再来，都只见一扇不开的门；失去故友的痛，比你预想得慢。"}, {"label": "烧信明志，不留此人东西", "effects": {"义": 2, "忍": -1}, "feedback": "火舌卷起字迹，你看着最后一点灰落下。你痛快了片刻，也知道将来若要证明他参与设局，少了一件他亲笔写下的东西。"}]}, {"ch": 3, "title": "陌生人的宝刀", "text": "集市上，一个汉子提刀与你擦肩，刀鞘碰到你的枪杆。他不但不赔礼，还冷笑你不识好物。刀一出鞘，刃光映得人眉目发寒，确是一把难得的利器。价钱高得足以挖空小家的积蓄，他却像笃定你会要，连退价都不肯。你一生练武，见到好刀难免心动，贞娘说过的城外退路也在脑中打转。你忽然分不清，这场相逢究竟是运气，还是别人知道你的眼睛会落在哪里。", "options": [{"label": "记卖刀人特征，再议买卖", "effects": {"证": 2, "钱": -1}, "feedback": "你请街边熟识的铺主见证，记下姓名与口音。刀仍买得昂贵，至少日后有人能说出，它何时从谁手里到了你这里。"}, {"label": "倾囊买刀，认为武人不该错过", "effects": {"钱": -3, "势": 2}, "feedback": "你付出银钱，反复试了刀锋，越看越觉得称手。回家时袖中空空，院中那盏灯仍为你亮着，你不敢马上说出价格。"}]}, {"ch": 3, "title": "传话的人不报姓名", "text": "过了两日，两个承局来请，说太尉听闻你得宝刀，要当面比较。他们不肯留下手帖，只催你快走，免得误了上官兴致。你在太尉府供职多年，知道有些地方持兵不能入，有些命令却从来只用口传。门口的石狮在午后晒得发白，承局嫌你更衣太慢，已经伸手替你拿刀。若这是赏识，推辞会失了前程；若这是陷阱，跟着走便再没有自己的步子。", "options": [{"label": "要求留名，并先托人报信", "effects": {"证": 2, "路": 1}, "feedback": "你让两人说出所属值房，又请邻人把去处告诉岳父。承局不耐烦地应了，留下的名字真假未明，消息却已出了门。"}, {"label": "随他们去，不敢让太尉久候", "effects": {"势": 2, "忍": 2}, "feedback": "你把家中门闩扣好，跟着往府里走。一路没有人同你说比较宝刀的细节，你把每次想问的话又压回喉咙里。"}]}, {"ch": 3, "title": "偏院后的禁地", "text": "承局领你穿过几进院落，让你在一间堂前候着。四周安静得不像寻常接待教头的地方，牌额蒙在阴影里，守门军卒见了刀鞘，都避开眼睛。你忽然认出白虎节堂的形制，心中一沉。太尉的脚步已从屏风后传来，承局却不知何时退到了远处。你做过无数次枪棒拆解，知道对手的力一旦压实，便不能再站在原地等它自己松开。", "options": [{"label": "立刻解刀退至门外，大声说明来由", "effects": {"证": 2, "势": -2}, "feedback": "你把刀横放在石阶上，请守卒见证自己并未擅闯。太尉仍喝令拿下，至少审案时不再能轻易把所有经过说成你蓄意行刺。"}, {"label": "留在原处，盼太尉听完解释", "effects": {"忍": 2, "势": -1}, "feedback": "你握着刀鞘躬身行礼，解释尚未说完，罪名已从他口中落下。那些人等的，正是你带刀站在这里的这一刻。"}]}, {"ch": 3, "title": "牢门关上之前", "text": "军卒将你反剪双手，刀被收走，帽子滚进泥里。你想起早晨出门时贞娘问回不回家吃饭，自己只答太尉相召，不会很久。一个熟悉的狱卒认出了你，趁人不察，问有什么口信要带。他不敢替你递状子，家常话却还有办法送出去。你能说的话极少，每一句都可能落入别人耳朵。牢门铁环响起，外头的白昼从一道缝里，迅速缩成了细线。", "options": [{"label": "叫家中立即移住岳父处，别来求衙内", "effects": {"家": 2, "迁居": 1}, "feedback": "你只说旧宅漏雨，先去城外歇几日。狱卒听懂了这句绕着说的求救，收下一点押金，答应今夜就把话送到。"}, {"label": "请岳父搜集证人，设法申诉", "effects": {"证": 2, "钱": -1}, "feedback": "你报出承局、铺主和使女的名字，恳求先记下证言。口信出了牢门，家人也开始奔走，暂时还没人顾得上收拾出城的行李。"}]}, {"ch": 4, "title": "墨迹比铁更重", "text": "推官将供状摊在面前，说只要承认带刀误入，未必不能从轻；若一味攀扯太尉，便是谁也救不了你。你读着供状，发现请去看刀的两名承局不见了，等候的偏院也被改成自行潜入。一个人可以被绳索绑住，也可以被几行替他写好的字绑住。牢里还有别的犯人，他们看着你拿笔，没人出声。你想到身后的妻子与岳父，第一次发现，公道和活下来竟会被摆在天平两端。", "options": [{"label": "逐项改正经过，拒认行刺", "effects": {"证": 2, "势": -1}, "feedback": "你承认自己失察，却不认从未生出的杀心。推官烦躁地收走供纸，重审多拖了两日，你留下的每一处勾改仍有价值。"}, {"label": "先认误入，求保住性命", "effects": {"忍": 2, "势": 1}, "feedback": "你用尽力气把字写稳，换来一句可以斟酌。供状没有把你写成刺客，却也没有写出是谁一步步引你走到了堂前。"}]}, {"ch": 4, "title": "差役递来的账", "text": "牢饭粗粝，水里浮着一层灰。差役蹲在栅栏外，说上头打过招呼，想少受些皮肉苦，总要有银钱。他报的数目不是天价，却正好够贞娘在外赁一间屋。你听见隔壁有人挨板，叫了几声便没了声音。墙上刻着许多姓名，有些已被新灰盖住。你不知道哪个价码才是真的，也不知道这场交易结束后，会不会还有另一只手来要同样的钱。", "options": [{"label": "付一半，托熟人核实用途", "effects": {"钱": -1, "证": 1}, "feedback": "你给的钱不够买一句保票，倒换来推官身边一个识字人的照应。他答应替你留一份供状副本，免得改了又改。"}, {"label": "保留银钱，要求按牢规供给并记下差役姓名", "effects": {"钱": 1, "证": 1, "忍": 1}, "feedback": "你没有拿出最后的盘缠，把缺食缺水的日期记下来。差役不肯立刻松口，身上的难受仍须挨过，家中的应急钱却没有又被一层层索走。"}]}, {"ch": 4, "title": "门外的人不该一起坐牢", "text": "岳父隔着栅栏来见你，鬓边几日便白了许多。他说贞娘不肯走远，怕哪天放你出来，家门却锁着。你想起她曾被哄上陆宅楼梯，知道等候并不天然安全。牢里风冷，你把手缩进袖中，不想让老人看见腕上磨破的皮。岳父带来一双新鞋，鞋底缝得密密实实，是她熬夜纳的。你必须决定，要用这次难得的相见讨论冤案，还是先把活人的去向讲明白。", "options": [{"label": "请岳父带她出城，约鲁智深护送", "effects": {"家": 2, "护送": 1}, "feedback": "你把每个接头处说得很慢，直到老人复述无误。离别还未发生，你已经开始想念；可留在京中的每一天，都更像替别人守着一只笼子。"}, {"label": "嘱家人别再送银，守好小家", "effects": {"钱": 2, "家": -1}, "feedback": "你把省下的银钱还给岳父，劝他不要被差役层层榨取。他点头离去，仍不放心把女儿带得太远，出城的打算暂时搁下。"}]}, {"ch": 4, "title": "判词中的沧州", "text": "判决落下，你免死，刺配沧州。牢中有人说你已算有福，连你自己听见命保住了，也险些跪下谢恩。可是烙印烧上脸颊时，那点侥幸立刻被疼痛逼散。官身、旧宅、与妻子同行的街道，都像被一笔划出。押解公文上写着到达日期，仿佛从东京到沧州只是纸上的一条直线。你用舌尖抵住牙关，不许自己叫出声，心中却有一扇门，已经不能再像从前那样关严。", "options": [{"label": "把判牍副本和口供一并留给岳父", "effects": {"证": 2, "路": 1}, "feedback": "你将纸交到老人手中，请他先护人，再护纸。公道或许很远，你至少留下了不是由太尉府独自保管的另一份经过。"}, {"label": "写下放妻文书，盼她脱离牵连", "effects": {"忍": 2, "离书": 1}, "feedback": "你把最难写的几个字写完，交出去时不敢看她。休书可以断官文中的名分，却不能命令她从此不再爱你，也未必能挡住恶人的手。"}]}, {"ch": 5, "title": "她没有接那张纸", "text": "长亭送行的人不多，贞娘挽着包袱站得笔直。她看完放妻的文书，没有哭闹，只问你是不是以为替她作完这个决定，就算已经护好了她。你被问得说不出话。押解公人董超、薛霸催你动身，说配军哪来这样多家事。岳父把热汤捧在一边，手抖得洒出几滴。你们面前明明是一条出城的官道，落在每个人眼里，却像一把要把一家人从中割开的刀。", "options": [{"label": "把选择还给她，约定平安后再议归处", "effects": {"家": 2, "离书": -1}, "feedback": "你承认自己害怕，也承认不该用一纸文书替她决定余生。她把纸折好，说先让两个人都活下来，其余的话留到相见时说。"}, {"label": "坚持让她另择安稳人家", "effects": {"忍": 2, "家": -2}, "feedback": "你低头说了许多自己都难信的话，终于看见她眼中的光暗了一些。她没有答应改嫁，只把包袱放到你脚边，退回父亲身旁。"}]}, {"ch": 5, "title": "鞋底里的针脚", "text": "新鞋看似普通，穿上却略硬。贞娘趁公人喝汤时提醒你，别急着拆，走到实在无路时再看。你知道她不善说场面话，能留给你的都藏在手上做出来的东西里。薛霸掂了掂包袱，嫌重，想把干粮扔掉。远处几个路人装作看景，眼神却总往你们身上飘。你能当场争，也能忍着上路，每一种反应都可能让他们看出你还藏了什么。", "options": [{"label": "护住鞋与干粮，任他拿走外衣", "effects": {"钱": -1, "路": 2}, "feedback": "你脱下稍值钱的夹衣换他们松手，新鞋留在脚上。鞋底藏的碎银和一处客店名号，后来能替你换到的不只是一餐饭。"}, {"label": "给公人一些盘缠，求路上照应", "effects": {"钱": -2, "忍": 2}, "feedback": "董超接了钱，嘴上好说，薛霸却仍不耐烦。买来的笑脸只维持一小段路，你从他们的眼神里学到，索取并没有天然尽头。"}]}, {"ch": 5, "title": "不能一起走的路", "text": "贞娘说愿跟着你走到沧州，押解公人嗤笑，说女子陪配军，传出去不成体统。你知道路上未必比东京安全，自己戴着枷，也未必真能保护她。岳父在城外有一位远亲，家里做染布生意，曾来借住过几日。若送她过去，至少能暂时离开衙内耳目；若让她随行，你每天都看得见她，却也把她放进了押解人的掌心。长亭后的柳叶被风吹得一齐翻白，你们等着最后一句话。", "options": [{"label": "请她先去远亲家，分路保全", "effects": {"家": 1, "异居": 1}, "feedback": "她终于点头，问你要不要再摸一摸她的手。你隔着木枷伸过去，许久才放开；两条路就此分开，也为重逢留下了可能。"}, {"label": "劝她暂回东京等正式安置", "effects": {"势": 1, "家": -1}, "feedback": "你把难处说给她听，却仍把安全寄托在将来。她回头望了城门一眼，知道那里有家，也有尚未离开的那双眼睛。"}]}, {"ch": 5, "title": "回头看见的人", "text": "官道转过土坡，送行人已变成细小的影子。你不敢再回头，怕一回头就走不动。薛霸敲着枷角，说前面还有长路，教头的威风该收了。你怀里藏着一张贞娘写的短笺，上面没有誓言，只说冷了多穿，痛了别硬挨。午后的尘土粘在伤口上，你第一次明白，日常的嘱咐也会成为一个人走进陌生世界时，最难放下的东西。", "options": [{"label": "默记沿途客店，寻找可靠传信处", "effects": {"路": 2, "钱": -1}, "feedback": "你装作问水喝，记下几处常接商旅的店名。每个地址都很小，合在一起，却能把你与故人的消息从官道之外接起来。"}, {"label": "专心保存体力，不再多问", "effects": {"忍": 2, "义": 1}, "feedback": "你收起短笺，跟着一步步走，省下了与公人争执的力气。路上的人来人往，你不再把每一张笑脸都当成援手。"}]}, {"ch": 6, "title": "滚水与烫伤", "text": "客店里没有多少客人，薛霸却特意要来一盆滚水，说给你洗脚。热气扑到脸上，你望着他不肯移开的手，知道拒绝也能被说成不服管束。一路的银钱并没有把敌意换成善意，反倒让他们确定你还有可榨之物。烫伤的脚若走不动，到不到得了沧州都难说。店主站在门边，像看见了一场雨，不愿问是谁把水泼到人身上。", "options": [{"label": "请店主作证，借凉水混洗", "effects": {"证": 1, "钱": -1}, "feedback": "你把话说得客气，却坚持让旁人看到水温。店主终于端来凉水，公人骂骂咧咧，没能把伤做得那样重。"}, {"label": "咬牙挨下，避免被寻别的罪名", "effects": {"忍": 2, "路": -1}, "feedback": "滚水浸过脚背，你疼得眼前发白，仍没有喊。翌日每一步都拉扯水泡，你开始明白，忍让不能让对方自动觉得够了。"}]}, {"ch": 6, "title": "树上的绳索", "text": "密林遮住日头，公人说歇一歇，替你把枷靠在树上。薛霸突然拿出绳索，你下意识闪身，董超已经拔起水火棍。他们没有再装作例行公事，说奉了陆虞候吩咐，要你到这里便算到头。名字从他们口中出来，你反倒静了一瞬。数年旧情、数十贯盘缠、数百里官道，最终都被收束成树干上一道绳套。你身上还有武艺，手脚却并不自由。", "options": [{"label": "拖住他们说话，设法挪到树后", "effects": {"证": 2, "路": 1}, "feedback": "你追问陆谦给了多少银，借他们争辩时把绳扣转开一点。棍子仍举起来了，你至少不再把喉咙直接交到绳索里。"}, {"label": "斥责他们，准备拼死一挣", "effects": {"义": 2, "忍": -1}, "feedback": "你挺起身子，连枷木都撞出一声闷响。两名公人被你的眼神逼退半步，很快又仗着你受制上前，林中忽然响起另一声暴喝。"}]}, {"ch": 6, "title": "禅杖落在棍前", "text": "一条禅杖横着扫过，董超手里的棍飞进灌木。鲁智深从树后冲出，骂得林叶都像在颤。你从没想过，长亭后那道若有若无的身影竟跟了这么远。他问你放不放过这两个畜生，杖头离公人的脸只有一寸。你看见他们跪下求饶，也想到杀了官差，鲁智深会为你背上怎样的罪。被救的人还没有喘匀，又必须替救命的人决定一次危险。", "options": [{"label": "留他们性命，逼写受雇供词", "effects": {"证": 2, "义": 1}, "feedback": "你请鲁智深停手，叫公人各写一份供词，互相画押。字未必能立刻救你，却让他们知道，这笔账不再只在他们主子手里。"}, {"label": "请和尚带你走，彻底脱离押解", "effects": {"路": 2, "势": -2}, "feedback": "鲁智深说走便走，替你挑开枷锁。你最终仍得设法取得沧州安置文书，官差的搜捕也从此成为绕不开的另一条路。"}]}, {"ch": 6, "title": "救命之外的托付", "text": "篝火烧起来时，你才看清鲁智深僧鞋磨穿了底。他说自己早看出两个公人不安好心，一路故意落在后面，等他们露出真意。你想向他磕头，他不肯，只叫你喝口热水。你们谈到东京旧人，火光照着一张张想念的脸。如今求他办的每一件事，都意味着他要再走一段险路；可有些事若此时不开口，再过十天半月，便可能只能听别人来报结果。", "options": [{"label": "请他回京核实妻子去向，先护活人", "effects": {"鲁约": 1, "护送": 1, "家": 2}, "feedback": "鲁智深把几处地址复述一遍，说先把人安置妥，再谈讨账。你听见承诺，不再只是听见好听的话，而是听见一双肯走路的脚。"}, {"label": "请他保全供词，找人上告", "effects": {"证": 2, "义": 1}, "feedback": "和尚收起供词，说替你找信得过的人留底。他没有许诺扳倒太尉，只答应不让这些纸悄无声息地变成灶灰。"}]}, {"ch": 7, "title": "一百杀威棒", "text": "牢城营门口，差拨高声唱着新配军的罪名。你站得笔直，他便说这人不知规矩，要先打足一百杀威棒。你知道身上的伤未好，硬挨下来，练了一辈子的腿未必还能听使唤。几名老囚把眼神投向你的包袱，又很快移开。门牌上写着依法收管，院中却连说话的轻重都有另一个价码。你伸手摸到鞋底藏银的位置，也想起那些银钱原本是为了将来的退路。", "options": [{"label": "拿出一份银，保住身体", "effects": {"钱": -2, "路": 1}, "feedback": "银钱从袖中递过去，规矩便忽然有了通融的余地。你没有为此觉得光彩，也不肯因羞耻而假装受伤不是要紧事。"}, {"label": "援引伤势与判牍，争缓行刑", "effects": {"证": 2, "势": -1}, "feedback": "你请求验伤，把条文一条条说清。差拨不愿担上当场打死人的责任，准你暂缓，往后的差事却多了几分刻意刁难。"}]}, {"ch": 7, "title": "柴庄来的一封信", "text": "午后，有人拿着柴大官人的书信来见管营。你曾在路上与柴进结交，他听闻你到营，特意托人照拂。管营前一刻还板着脸，见了封套便请你坐下。你看着同一张嘴换出另一种语气，既松了口气，也觉出一阵难堪。旁边有个犯人跛着脚求医，始终没人理会。你可以把这封信只用作自己的护身符，也可以试着让它的余荫落到别人身上一点。", "options": [{"label": "请管营准伤囚看医，同领这份情", "effects": {"义": 2, "势": -1}, "feedback": "你没有借势吆喝，只多说了几个名字。管营答应一次，柴进的人情也被你多花了一分，跛脚的囚犯却终于拿到药包。"}, {"label": "只谢自己的照应，免生旁枝", "effects": {"势": 2, "忍": 1}, "feedback": "你恭恭敬敬谢过管营，顺利搬进稍干净的屋子。窗外的呻吟没有立刻消失，你把信折好，心里知道自己欠下了什么。"}]}, {"ch": 7, "title": "小牢房里的同袍", "text": "夜里，一个老军替你送来热水，说姓李，年轻时也练过枪。他不问你的罪名，只说北地冬天硬，伤口要早收拾。你们聊到军营的旧日，发现许多本应记在名册上的人，早已在行伍中无声无息地没了。他拿出半块干饼分你，自己留着更小的那半。你现下手头不宽裕，仍能看出他脸色蜡黄，家中恐怕也靠这点工钱过活。", "options": [{"label": "回赠药钱，结一份不靠官面的交情", "effects": {"钱": -1, "义": 2, "李约": 1}, "feedback": "老军推了两次才收下，说有事尽可来叫。他不会替你改变营规，却愿在旁人都转过脸时，让你屋里多亮一盏灯。"}, {"label": "记下好意，留银应付未知差事", "effects": {"钱": 1, "忍": 1}, "feedback": "你认真谢过，把干饼吃完，没有许下空口回报。他仍照旧送水，交情停在门槛边，尚未走成能托付生死的一步。"}]}, {"ch": 7, "title": "写得出去的家书", "text": "你借来纸笔，终于能写第一封真正从沧州寄出的家书。提笔时有许多想问的话，落笔却怕每一句都被别人看见。你不知道贞娘是否已出城，也不知道岳父还能不能按旧住址收信。纸很薄，一旦投进官路，或许抵不过差役一句查验。老军说往南的盐商明早动身，能捎信，只是要等一个月才回来，官驿则快，却处处有眼睛。", "options": [{"label": "经盐商带暗号，请她只回安全处所", "effects": {"钱": -1, "路": 2, "信路": 1}, "feedback": "你没有把全部地址写在一处，用约好的细节证明是自己。信走得慢，却不必从太尉府熟悉的每一道门里经过。"}, {"label": "走官驿寄往旧宅，求快得回音", "effects": {"忍": 1, "势": 1}, "feedback": "你写下最熟悉的街巷，反复嘱咐送到本人手中。信很快离开营门，你也只能盼，旧宅门前等着收信的人还是家人。"}]}, {"ch": 8, "title": "新差事的来由", "text": "管营忽然换你去看守草料场，说那里清静，适合有武艺又不爱多话的人。老军听了并不高兴，替你收拾衣裳时，问是谁先向管营提的名字。你答不上来。草料供军，一旦出事不是小罪，门锁、交割、夜巡都须一一看清。窗外雪粒敲在瓦上，来送差帖的差拨已经不耐烦，催你天黑前就搬，仿佛多让你留一夜，谁的盘算便会落空。", "options": [{"label": "查交割簿，清点草垛与门锁", "effects": {"证": 2, "势": -1}, "feedback": "你把每处数目另抄一遍，还请老军见证。差拨嫌你多事，勉强按了印；草场如今缺了什么，不再能全推在你身上。"}, {"label": "即刻赴任，把清静当作照顾", "effects": {"忍": 2, "势": 1}, "feedback": "你带着行李随人过去，空空的草场比牢房宽敞许多。守夜的任务看似简单，原先由谁保管钥匙，却没有人主动说清。"}]}, {"ch": 8, "title": "坏掉的屋梁", "text": "草场小屋的屋顶被雪压得弯下去，墙根透风。老军说从前就坏，一直没人肯拨银修。你站在门口，能闻见潮草的气味，火盆若用得不当，整片草垛都可能烧起来。屋梁上挂着一双旧草鞋，不知上一任看守为何走得那样匆忙。修屋要耗自己的钱，不修则要把每个冬夜交给运气。你想到东京换过的新瓦，那时为的是安稳，如今为的是还能睁眼看见明天。", "options": [{"label": "出钱加固屋梁，并清出避火通道", "effects": {"钱": -2, "路": 2, "修梁": 1}, "feedback": "你同老军抬木补好最危险的一段，又把草垛间让出路来。袖里少了银，雪夜若有急变，脚下至少不再全是死路。"}, {"label": "只补门缝，留钱等春暖后再修", "effects": {"钱": 1, "忍": 1}, "feedback": "你把破布塞进风口，勉强挡住寒意。梁仍在雪下轻轻作响，草场看着与昨日一样，你却不敢再在火盆旁睡得太沉。"}]}, {"ch": 8, "title": "小店主人的提醒", "text": "沽酒回程，店主人拉住你，说近日有几张生面孔打听草场，像是从京师来的。他不愿多惹是非，只说有人给钱让他转告你安心做事，来人是旧识。你听见旧识两个字，胸口先紧起来。风刮过店檐，酒旗像被人扯住，你想起陆宅那扇合上的门。这里没有岳父，没有能随叫随到的同僚，你若再次把不对劲解释成人情，未必还有另一个野猪林。", "options": [{"label": "请店主记下样貌，转告老军暗中留意", "effects": {"证": 2, "李约": 1}, "feedback": "你谢过他，没有要求他冒险跟人。老军记住几张面孔，答应见到便绕路来报，一条小小的警戒线因此连了起来。"}, {"label": "装作不知，避免打草惊蛇", "effects": {"忍": 2, "路": 1}, "feedback": "你照常提酒回去，路上却换了两次走法。对方没能从你脸上看出什么，你也没有新增见证，后面的判断只能更多靠自己。"}]}, {"ch": 8, "title": "雪封之前的布置", "text": "傍晚，草场外的小路已积起薄雪。你把枪放在触手可及处，又看了看旁边山神庙的方向。老军说庙门还能开，背风处可借宿，别嫌神像破旧。你过去转了一圈，发现门后有块大石，挪开并不费力，屋顶却比草场结实。你曾以为练枪就是临阵制敌，如今才懂，知道哪里有一扇能关上的门，也是一种必须亲手学会的本事。", "options": [{"label": "把干粮与备用火石藏到庙中", "effects": {"钱": -1, "路": 2, "庙备": 1}, "feedback": "你没有等危险来了再找粮火。小包袱被藏在供桌后，里面不贵重的东西，会在最冷的时候替你保住一口热气。"}, {"label": "留守草场，严格照章巡夜", "effects": {"势": 2, "忍": 1}, "feedback": "你把巡更时辰记在墙边，一圈圈踩出自己的脚印。做得再齐整，也只能证明你尽了本分，不能保证别人不来毁掉它。"}]}, {"ch": 9, "title": "等来的半张纸", "text": "盐商送来一封转了几手的信，封口被雪水浸皱。你先看约定的针脚，又看开头那句只有家人懂的话，才敢把纸拆开。信里没有写满地址，几处称呼都故意省去，连一声平安也说得极克制。你从纸上闻不出家里的味道，只闻见一路客店的烟火气。隔了这样远，写信的人要相信你读得懂，读信的人也必须承认，有些没写下来的事，并不等于没有发生。", "options": [{"label": "核对暗号再回信，不催她透露藏身处", "effects": {"信路": 1, "家": 2}, "feedback": "你把最想问的那几句话压下，只回了自己能走、能吃。确认活着比索取地址更要紧，这封信终于没有变成追人的线。"}, {"label": "追问完整地址，盼尽快团聚", "effects": {"家": 1, "路": -1}, "feedback": "你在纸边写下长长的问句，怕她看不见又描重一遍。思念是真的，完整地址若落错一只手，同样会是真的危险。"}]}, {"ch": 9, "title": "可靠的人也有难处", "text": "带信的盐商说下趟要换路线，沿途有人查流人家属，他不能再照旧替你捎。他家里还有两个孩子，一旦被扣货，便是全家生计。你不能拿自己的苦，抹掉别人承担风险的权利。桌上的酒已经冷了，你把杯子推过去，他摇头不喝，等你一句不会逼他的答复。若要另找信路，须多花银钱；若断掉通信，下次重逢或死讯，都只能等命来送。", "options": [{"label": "补足盘缠，请他只代找下一个可靠人", "effects": {"钱": -2, "路": 2, "信路": 1}, "feedback": "你没有买他的命，只请他介绍一条有退路的消息链。他放松下来，写了一个不会直接连到你家人的商号，约你只凭暗号相认。"}, {"label": "停止托信，免得把别人卷进来", "effects": {"义": 2, "信路": -1}, "feedback": "你把信收回，认真向他道谢。保住他的安稳也是你作的选择，可从此每个无消息的夜晚，都要自己担着那份不知道。"}]}, {"ch": 9, "title": "当家的不是一张纸", "text": "你对着旧时写下的放妻文书想了许久。那张纸到底帮了谁，你没有把握；它可能让家人少受官面牵连，也可能让求助的人先问一句，你既已放妻，为何还来管她。你渐渐学会不再把字写得漂亮就当事情办妥，真正的保护要有人到、要有地方住、要有饭吃，还要让被保护的人自己知道下一步怎么走。窗外积雪渐厚，屋里每一件东西都像在等一个确实能落地的安排。", "options": [{"label": "将藏银与接头暗号另写一份送出", "effects": {"钱": -1, "路": 2, "接头": 1}, "feedback": "你把地点分开写，避免一封信暴露全部路径。用掉的是能救急的银，换来的是别人即使见不到你，也知道该往哪里去。"}, {"label": "写明自己仍认这段姻缘，先给她定心", "effects": {"家": 2, "忍": 1}, "feedback": "你把害怕和悔意都写进信里，不再只说保重。这样的承诺无法替代护送，却能让她在孤身支撑时，知道没有被你推开。"}]}, {"ch": 9, "title": "雪夜未眠", "text": "火盆只剩一点暗红，你没有再添炭，怕夜里睡沉了，雪把门堵住。几封书信被你压在衣内，贴着胸口并不温暖，只是不舍得放远。你想象东京巷口卖炊饼的人收了摊，岳父将门闩放下，贞娘把灯拨亮。那些画面越平常，越让人难过。可你已经开始懂得，想念不该只把自己困在旧屋，它也应催人检查鞋、枪、粮与人情，看看明天真来了，还有什么能用。", "options": [{"label": "整理轻便行囊，把证物缝进夹层", "effects": {"路": 2, "证": 1}, "feedback": "你只留下能带走的东西，旧信贴着供词，各占薄薄一层。若屋子留不住，人还有走出去的准备，真相也能跟着活人移动。"}, {"label": "留在炉边练气，恢复伤后的身手", "effects": {"义": 1, "忍": 2}, "feedback": "你一呼一吸，反复活动受过伤的腿。许多事情由不得你，骨头和力气却仍能一点点练回来，不必全交给别人安排。"}]}, {"ch": 10, "title": "被压塌的小屋", "text": "风从黄昏起便没有停，雪先堆住窗，再堆上屋梁。你出去打酒，回来时听见一声闷响，小屋塌进白茫茫里，只剩半截门框。你站在原地，想到自己若晚走一刻，眼下躺在梁下的便不是铺盖。草料暂未起火，炭盆却被压在屋里，不知还有没有余烬。你可以先找火种，也可以直接往山神庙去，带着一身寒气承认，所谓安稳有时不过是还没有塌下来的那点空隙。", "options": [{"label": "确认炭火已灭，取出枪与少量行李", "effects": {"证": 1, "路": 2}, "feedback": "你扒开积雪看清火盆，把还能用的东西拢在一起。回头的脚印很快被风抹平，你至少知道下一场火不会是自己留下的。"}, {"label": "立刻去庙中避寒，不再冒险翻屋", "effects": {"忍": 2, "钱": -1}, "feedback": "你拎着酒与枪离开，把更多衣物留在塌屋下面。冻僵的手总算能在庙中缓过来，今后却要靠更少的东西继续走。"}]}, {"ch": 10, "title": "庙门那块石头", "text": "山神像的彩漆剥落，供桌上只有一层厚灰。你把门掩上，顺手挪石挡住，背着枪坐到避风处。外面白得看不见路，风把庙檐吹出长长的呜咽。酒入腹时，你忽然想到少年读过的英雄故事，里面总有人受难后遇见贵人，随后一切便得转机。轮到自己，只见一座旧庙，一截残烛，还有不知道寄到没有的家书。你并不想当故事里的人，只想不再被下一扇门骗进去。", "options": [{"label": "检查后窗与屋顶，先认清可退之处", "effects": {"路": 2, "忍": 1}, "feedback": "你摸清一扇能开的后窗，在墙角标了脚下深浅。门挡得住风，不见得挡得住追兵，有了第二条路，心才略略稳住。"}, {"label": "先烘衣暖身，保存突围的力气", "effects": {"义": 1, "忍": 2}, "feedback": "你把湿衣拧干，坐近残火，又把枪放在膝上。身上的颤抖慢慢止住，你终于能听清风里夹杂的另一些声音。"}]}, {"ch": 10, "title": "隔门传来的名字", "text": "脚步在庙外停下，几个人边推门边说草场烧起来了。你听见差拨的嗓子，又听见陆谦压低声音发笑，说烧死也好，逃出也要背军粮失火的死罪。你用手按住枪杆，几乎能感觉到掌心木纹。那些你曾替他们找过的理由，在这一刻连灰都不剩。门外还谈到东京旧事，仿佛你妻子的哭声、你身上的烙印，都不过是酒席上可换来功劳的闲话。", "options": [{"label": "忍住先听完，将同谋与计划记牢", "effects": {"证": 2, "忍": 1}, "feedback": "你把每个人说的话记在心里，不再替他们改成好听的意思。证据不只是为未来伸冤，也是帮你终于确认，自己没有错听这些恶意。"}, {"label": "立即喝破，逼他们面对活着的你", "effects": {"义": 2, "忍": -2}, "feedback": "你隔门喊出陆谦的名字，外面陡然静了。他们以为世上只剩一具烧焦的配军，没想到你还握着枪，也还记得旧情是怎样被践踏的。"}]}, {"ch": 10, "title": "门内最后一次忍", "text": "火光从门缝里映进来，雪却还在下。你知道不论今夜出不出手，草场的火都会追到你身上，太尉府也不会因你又忍过一次而停手。旧日教头的身份在身后站着，像一件再也穿不回的袍子。眼前能做的不是把过去还原，而是决定接下来由谁承担危险。你慢慢站起，膝头没有再发软，枪尖在残烛里亮了一线。庙外的人开始商量换一处门进去。", "options": [{"label": "先开后窗留退路，再正面迎敌", "effects": {"路": 2, "义": 1}, "feedback": "你把门后的石头挪开一线，又确认后窗没被堵死。反抗并不妨碍谨慎，你要活着离开，不是把命只换成一瞬间的痛快。"}, {"label": "堵牢后路，背水一战", "effects": {"义": 3, "忍": -2}, "feedback": "你把酒碗放下，双手握稳长枪。此刻再没有人能替你代说一段求情，你的每一个动作，都由你自己承担到底。"}]}, {"ch": 11, "title": "枪尖上的旧名", "text": "庙门开了，陆谦一脚陷进雪里，脸上的神情从错愕变成哀求。他叫你兄长，说自己受人逼迫，事到如今才明白不该。你已经听完他隔门说的每一句，此刻再听熟悉的称呼，竟没有从前那样疼。另两人绕到侧面，想趁你分神夺路。火在远处越烧越亮，你知道没有多少时候能让他们把责任推来推去，更没有义务再陪一场假装还认得彼此的叙旧。", "options": [{"label": "先制住持械的两人，再问陆谦", "effects": {"证": 1, "义": 2}, "feedback": "你没有被求饶带走目光，枪尾横扫，逼退侧面的刀。陆谦终于看见，你不再只是他记忆中那个总替旧友留余地的教头。"}, {"label": "逼陆谦交代主使，冒险多留片刻", "effects": {"证": 2, "路": -1}, "feedback": "你要他把高衙内的名字说出来。他说了，还想编造自己如何不得已，直到身旁同伙趁机扑上，你才不得不收回那点时间。"}]}, {"ch": 11, "title": "不能再寄望的官门", "text": "反击结束时，雪地只剩凌乱的脚印和掉落的兵器。你衣袖擦破，喘息在夜里一团团散开。这里的经过必会被写成另一种样子，你明白再回营中解释，等着你的不会是第一次重审的耐心。可你仍有可能把火场外的物证交给可靠之人，让真相不全埋在大雪下。远处已有铜锣声，你必须在追兵到来前决定，自己能带走什么，又必须舍弃什么。", "options": [{"label": "取信物与差牌，绕行送给老军", "effects": {"证": 2, "李约": 1}, "feedback": "你挑出能说明身份的几样东西，不在尸火旁多留。老军收下时只叹一声，叫你快走，他愿替你守住一份清楚的经过。"}, {"label": "弃下重物，趁雪未停远走", "effects": {"路": 2, "钱": 1}, "feedback": "你扯下碍事的衣角，把能吃的干粮收进怀里。真相没有因此消失，只是暂时顾不上替它找一张能放得下的桌子。"}]}, {"ch": 11, "title": "回头不是归途", "text": "你走到林口，回望草场，火已烧透半边天。自己曾在那间小屋里算过春天的日子，想着攒下银钱，把家人接来；如今屋梁和草垛都在同一片红光中沉下去。你忽然想笑，笑意出来却像哽住。世上有人可以一纸调令毁掉另一人的全部打算，受害者若不肯顺从，反倒要被追问为何走到绝路。你把枪攥紧，脚下是尚未被人踏过的雪。", "options": [{"label": "给救过你的店主留暗号，不贸然登门", "effects": {"义": 1, "路": 2}, "feedback": "你绕到约定的树下，刻下只有对方认得的记号。没有把追兵直接带去他家，也没有让他误以为你早已死在火里。"}, {"label": "忍痛断掉附近一切联络", "effects": {"忍": 2, "路": 1}, "feedback": "你不再靠近熟人的门，独自向远路走去。他们或许会替你担心，你也只能把这份难过当成不把灾祸引过去的代价。"}]}, {"ch": 11, "title": "逃亡者的第一夜", "text": "破庙远了，城池也远了，饥饿和伤痛重新追上来。你在一处空牛棚歇脚，把被雪打湿的信重新贴好。那封信并没有告诉你前面该怎么走，只让你记得自己不是从火里凭空生出来的亡命人。你有过家，有过朋友，也还欠着许多活人一句交代。天亮后会有人搜路，牛棚不可能永远藏住你，柴进的庄子则是一处可能愿意先听你开口的门。", "options": [{"label": "向柴庄求一处暂住，明说今夜经过", "effects": {"路": 2, "柴约": 1}, "feedback": "你选了绕远却少关卡的路，不把柴进当作替你销罪的神仙，只求一顿饭、一夜灯和商量下一步的余地。"}, {"label": "先找商旅换衣，改换身份再去", "effects": {"钱": -1, "路": 2}, "feedback": "你用余银换了粗布外衣，把显眼的物件包好。身份可以暂藏，脸上的刺字却还在，往后每遇一双眼睛，都须多想一步。"}]}, {"ch": 12, "title": "被接住的一夜", "text": "柴进没有先问你惹了多大祸，只叫庄客烧水、煮饭。他说北地这般风雪，愿来的先有一碗热汤，别的话明日再讲。你端着碗，手忽然抖得握不住，险些把汤洒在衣襟上。连日来必须自己撑住的那股劲，在有人说可以歇一歇时反而松了。墙上挂着弓刀，院外有马嘶鸣，你没有忘记追兵，却终于不用每听见一声脚步便去摸枪。", "options": [{"label": "坦言危险，请柴进按实情决定帮到哪步", "effects": {"义": 2, "柴约": 1}, "feedback": "你没有把庄子拖进一场不知根底的祸。柴进听完点头，愿帮你走下一程，也划清哪些人不能随意卷入，你因此更信得过这份照拂。"}, {"label": "先养伤，不在众人面前多谈", "effects": {"忍": 2, "家": 1}, "feedback": "你把热汤喝完，承认自己此刻还讲不清。柴进没有催问，留了安静的客房，许多压住的疼痛才一点点从身体里浮出来。"}]}, {"ch": 12, "title": "迟来的消息袋", "text": "庄客拿来一个小布袋，说早有人托着，见到你本人才能拆。袋里有家人的消息，也有沿路转递的费用记录。你认得一处针脚，仍坐了很久才伸手。命运并没有因为你终于敢反抗，就替你把先前忽略的事一并补好；有人能躲开追索，有人会被困在无援的门里，取决于消息、银钱与真正到场的人。布袋很轻，几乎能被风吹走，你却觉得双手像托着整座东京。", "options": [{"label": "亲自核对信使经过，接住全部消息", "effects": {"证": 2, "家": 1}, "feedback": "你问清人在哪段路上接到信，哪些话亲耳听见，哪些只是传闻。消息不一定如你所愿，至少不让假回音再替恶人蒙住事实。"}, {"label": "先独自读信，容自己安静片刻", "effects": {"忍": 2, "义": 1}, "feedback": "你请众人暂避，坐在门内拆开布袋。你不必把每一滴眼泪都藏成体面，也不能把不肯看的那部分当作从未发生。"}]}, {"ch": 12, "title": "家书不是判词", "text": "你读完回音，久久没有合上纸。纸上能写下的是地址、日期和几句转述，写不全的是一个人在门内守过多少夜，又有多少次想求援却不知道该信谁。你从前总以为只要自己扛住，家里就能少受一些苦，如今才知道，独自承受有时也会让另一人被留在危险之外，既不知情，也无从选择。柴进让庄客添了灯，灯芯烧亮，你终于能看清纸上每一个字。", "options": [{"label": "整理仍能执行的接应，先护其余亲人", "effects": {"路": 2, "接头": 1}, "feedback": "你把情绪放在身边，不再让它独占整张桌子。已经发生的无法抹去，仍活着的人却不能再等你把悔恨想得周全。"}, {"label": "把回音缝入衣内，以此记住代价", "effects": {"家": 2, "忍": 1}, "feedback": "你将纸包好，连同从前那封短笺放在一起。接下来的每次选择，都不再只问自己能忍多久，也要问别人正在替这份忍承受什么。"}]}, {"ch": 12, "title": "柴进指向水泊", "text": "风雪渐止，庄子却不能长留一个遭缉捕的人。柴进提到梁山泊，那里有朱贵接引，也有容不容得下新人、愿不愿意讲道义的难题。他没有把水泊说成净土，只说你如今需要一处官府暂时伸不到手的地方。你看见庄外一个年轻客人正在练棒，动作里有不服输的劲；每个人来这里，都有尚不愿给别人看的伤口。你要去的也许不是归宿，只是下一处必须亲自认清的门。", "options": [{"label": "带荐书上路，另留一份家书转递法", "effects": {"路": 2, "信路": 1}, "feedback": "你把梁山当作暂时落脚的地方，没有让它吞掉全部旧人关系。柴进收下转信的法子，答应有确切消息再传，不替你编希望。"}, {"label": "请柴进直接替你说情，先求安身", "effects": {"势": 2, "柴约": 1}, "feedback": "荐书写得郑重，你把它贴身收好。门能否打开还要看山上的人，你却先借这点承诺，让自己走过了离庄时那段漫长官道。"}]}, {"ch": 13, "title": "酒旗下的暗门", "text": "酒店临着芦苇，桌上酒壶擦得干净，伙计却总先看客人鞋上的泥。朱贵认出柴进的荐书，笑容很快收敛，说上山容易，留下未必只凭武艺。你把枪靠在桌边，听见河上传来桨声。店里有人因欠一碗饭钱被赶走，也有人不过递个眼色便被引入后门。天下的门换了地方，门槛却未必就低。你要怎样走进去，会让接引的人先把你当成什么样的人。", "options": [{"label": "先替穷客付饭钱，再谈自己的去处", "effects": {"钱": -1, "义": 2}, "feedback": "朱贵看了你一眼，没有多说。那个客人喝完最后一口汤才离开，你们的谈话因此晚了一刻，却少了点只顾自己上岸的急迫。"}, {"label": "出示荐书，照规矩等接引", "effects": {"势": 2, "忍": 1}, "feedback": "你不在陌生地界先作主人，安静候到船来。朱贵认可你的稳重，山上的规矩究竟如何，仍要见过寨主才知道。"}]}, {"ch": 13, "title": "芦苇中的小舟", "text": "小船入泊，水路比陆路更难记，芦苇一转便遮住来处。摆渡人问你是否会水，你摇头，他便递来一截系腰的绳。你曾在校场指挥几百人，却在这条晃动的小舟上不得不信一个陌生船夫。远山有烟，岸边有人轮岗，梁山不是传说里的几张酒桌，而是一处要吃粮、要守口、也要决定谁能登岸的活地方。你想起自己将来若要接人，这些水路都得有人肯引。", "options": [{"label": "记渡口暗记，与船夫互通姓名", "effects": {"路": 2, "钱": -1}, "feedback": "你付足船钱，认真问了几处危险浅滩。船夫记住你肯听劝，来时的路终于不再只是别人握在手里的秘密。"}, {"label": "专心稳住身体，暂不打听山门", "effects": {"忍": 2, "势": 1}, "feedback": "你把枪横放船底，不乱挪动。摆渡人放心了些，水道仍像一张折好的图，尚未向你展开其中的纹路。"}]}, {"ch": 13, "title": "王伦的酒席", "text": "王伦亲自设酒，看荐书时笑得周到，问起你身手时却把杯子放下。他说山寨粮少房窄，怕委屈东京来的教头。你听得明白，一个不愿让你留下的人，能把拒绝说成替你考虑。杜迁、宋万在旁打圆场，既惜你武艺，也看寨主脸色。你现下有伤、有案，没有能轻易转身离开的好去处，却仍不愿把别人施舍一晚住处，当作可以任意辱你的凭据。", "options": [{"label": "直说愿出力守寨，不争座次", "effects": {"义": 2, "势": -1}, "feedback": "你把可做的事摆在桌上，不拿旧官职压人。王伦暂时找不到话驳，眼中的戒备却没有减，他担心的从来不只是粮米。"}, {"label": "耐心听完，接受先住几日再议", "effects": {"忍": 2, "势": 1}, "feedback": "你端起酒杯，没有逼对方当场表态。眼下有了床铺和热饭，能否长住，却被交给一个不断往后挪的日期。"}]}, {"ch": 13, "title": "窗外的三盏灯", "text": "客房窗外，巡夜的灯依次经过。你以为离开牢城便不必再看别人脸色，如今才知，官门之外照样有人拿位置作锁。一个小喽啰送来被褥，小声说寨中许多人愿留你，只是不敢在席上说。你不愿立刻拿这些私语作筹码，也明白若从不听旁人的难处，自己永远只能等寨主一句话。山风扑着窗纸，旅途中的每一处暂住，都在问你想把自己活成谁。", "options": [{"label": "帮巡夜者补好枪杆，先同做事的人相熟", "effects": {"义": 2, "路": 1}, "feedback": "你没有许诺改变山寨，只替他们把眼前能修的东西修好。几张原本只会点头的脸，渐渐愿意同你讲实话。"}, {"label": "闭门养伤，免被说结党", "effects": {"忍": 2, "钱": 1}, "feedback": "你收好枪，不参与山下议论。几日伤势确实好了些，山寨里对你的认识，也仍停在王伦想让人知道的那一面。"}]}, {"ch": 14, "title": "被要求交出的东西", "text": "王伦终于开口，说山中规矩，入伙要纳投名状：下山杀一个过路人，带头来证明胆气。你听到这里，先看了一眼荐书，柴进的名字在桌上，没能替无辜者挡下这句话。王伦知道你戴罪而来，笃定你为了落脚会把底线再往后挪。席间有人想劝，见他板起脸便闭了嘴。你不是不敢杀人，正因为见过草场的火，才更知道谁都能用一句不得已，把别人的命换成自己的门票。", "options": [{"label": "当面拒绝伤害无辜，要求以护寨本领代替", "effects": {"义": 3, "势": -2}, "feedback": "王伦把脸沉下去，说不纳便走。你没有获得一阵掌声，只有席间几道不再躲闪的目光，看见你说了什么，也看见你愿担什么。"}, {"label": "先领三日期限，下山另寻不害人的交代", "effects": {"忍": 2, "路": 1}, "feedback": "你没有在酒席上把话说死，带枪下山。多出来的三日不是解决，只是让你还有机会找一条不把陌生命换成床铺的路。"}]}, {"ch": 14, "title": "第一日的商旅", "text": "山道上过来一队挑担的人，走得很慢，担里不是金银，是北地运来的破皮货。为首者看见你枪尖，立刻把手举起，说货已亏本，求留一条命给孩子过冬。你本没有要杀他的念头，却仍从他脸上看见自己如今被当成了什么。路边草叶挂着霜，他等着你的决定，甚至不敢问能不能坐下。山上的期限在催，你的饥饿也在催，谁都可以成为你向自己辩解的借口。", "options": [{"label": "放行并提醒绕开前路伏哨", "effects": {"义": 2, "势": -1}, "feedback": "挑夫一再道谢，走出很远还回头看。你空着手回来，知道王伦又多一条嫌你的理由，也知道今天没有一个孩子因你失了父亲。"}, {"label": "留下少量粮钱作借，写明归还凭据", "effects": {"钱": 2, "证": 1}, "feedback": "你不许随从动刀，按数借走粮钱，给了有姓名的字据。这仍是强人拦路，你没有因此自称清白，只把欠账记进了自己身上。"}]}, {"ch": 14, "title": "空手回寨的饭", "text": "晚饭时，王伦当众问你有没有带回东西。小喽啰把饭碗放在你面前，又被他一个眼色喝住。你忍了一路的饿，闻着热饭的味道，才发现羞辱不必用板子，也能一下下打在人最软处。杜迁劝他别坏了山寨待客的名声，王伦只说规矩人人一样。你若掀桌，旁人会说你吃不得苦；你若一口口咽下，也未必换来明天不用再去的体谅。", "options": [{"label": "把不杀无辜的话再说一遍，接受少食", "effects": {"义": 2, "忍": 1}, "feedback": "你没有夺碗，也没有改口。饭比旁人少，夜里确实饿，你却不再因饥饿便假装那道命令忽然有了道理。"}, {"label": "借机指出规矩只用来排挤新人", "effects": {"势": -2, "证": 2}, "feedback": "席间静下来，有人终于问从前哪位头领照此交过。王伦勃然变色，你把他不愿面对的问题放到了所有人都能听见的地方。"}]}, {"ch": 14, "title": "第二日的脚印", "text": "翌日，你又被派到山下。雪地里有新脚印，步幅稳，落脚深，来人背着重担，却没乱了重心。你看出是行伍中人，山上跟来的喽啰却兴奋，说总算来了一个像能带出钱财的。你提醒他们莫轻举妄动，他们听不听，取决于你是不是只在寨主面前才像个客人。一个有武艺的人，可以拿本领替最弱者压低声音，也可以先拦住自己身后已经举起的刀。", "options": [{"label": "命众人退开，独自问路不先出枪", "effects": {"义": 2, "证": 1}, "feedback": "喽啰不甘心，仍被你挡住。来者看清你没有先抢他的行囊，神情缓了半分，紧握兵器的手却没有松开。"}, {"label": "依山寨要求拦路，但只许比武不许害命", "effects": {"势": 1, "义": 1}, "feedback": "你把规矩先说给自己人听，再横枪拦住来者。对方见你枪势严整，知道不能轻看，一场较量已难避免。"}]}, {"ch": 15, "title": "青面客的枪路", "text": "来的是杨志，脸上青记醒目，眼神却比那道记更冷。他见过你的枪法，试探数合便报出你的旧职，两人忽然像在荒路上认出了同一处塌掉的屋顶。你们都曾把一身本领交给朝廷，如今一个守着回不去的名册，一个背着不能丢的包袱。喽啰还在旁边喊打，你听着他的喘息，知道对方不是一道供你完成投名状的题，而是另一个走到窄路的人。", "options": [{"label": "报出姓名，提出停手相谈", "effects": {"义": 2, "路": 1}, "feedback": "你收枪半寸，先给对方能停的空间。杨志没有立刻相信，却认得这不是怯战的手，余下几招便从夺命变成互相试底。"}, {"label": "认真分出高下，再谈去处", "effects": {"势": 2, "义": 1}, "feedback": "你不再留虚招，两支兵器撞得震手。较量很久仍难决胜，疲惫逼得两人都笑了一声，倒比席间客套更像认识。"}]}, {"ch": 15, "title": "同袍的两种盼头", "text": "坐到路边后，杨志说仍想寻个重新立功的机会，祖上的名声不能断在自己手里。你没有嘲笑他，过去的自己也曾这样想：只要有人认得本领，总还有一扇官门会开。可你如今知道，人的本领并不能决定别人打算如何使用他。山风吹过枪穗，你们各自把刀枪放在够得到的位置，既是警觉，也是彼此默认还没到可以完全放下的时候。", "options": [{"label": "告诉他白虎堂与草场经过，不替他下结论", "effects": {"证": 2, "义": 1}, "feedback": "你说清自己见过什么，不命令他必须与你同路。杨志沉默许久，仍想再试一次，你只能提醒他留一份不由上官保管的凭证。"}, {"label": "劝他留山，与自己合力改变寨中规矩", "effects": {"路": 2, "势": -1}, "feedback": "你第一次试着为一种别的生活说话，不只求别人收留。杨志迟疑后仍摇头，他有他的结，你没有资格替他一把扯断。"}]}, {"ch": 15, "title": "王伦想留谁", "text": "回寨后，王伦看杨志的眼神与看你不同。他说两位都留下最好，席间热情得像投名状从未存在。你很快明白，多一个能制住你的人，正是他先前缺的安心。杨志并未答应，王伦便频频劝酒。你手里的饭终于不再比旁人少，心却没有因此觉得被公平对待。世上有些宽待不是因为尊重你，而是因为某种让你难受的算盘暂时凑齐了数目。", "options": [{"label": "当众请撤投名状旧令，惠及后来人", "effects": {"义": 2, "势": -1}, "feedback": "你没有只领自己这一碗饭的情。王伦含糊答应，席间至少留下许多人亲耳听过的承诺，日后再拒人时须多找一层说辞。"}, {"label": "先接受席位，待站稳再作改变", "effects": {"势": 2, "忍": 1}, "feedback": "你把酒饮下，终于有了明确座次。留山是眼前最实在的成果，未改的规矩也仍在，不能因自己过关便当它不再伤人。"}]}, {"ch": 15, "title": "送别与留灯", "text": "杨志走的那天，你送到山脚。他把包袱重新扎紧，说若将来有缘，总还会相见。你看着他的背影，忽然明白英雄相惜并不一定以同上梁山作结，有时只是承认对方还有不愿放弃的盼头。回到寨里，房中多了一盏新灯，巡夜的喽啰说是朱贵叫人送的。有人没有在酒席上替你说多少漂亮话，却愿意把你往后的夜里照亮一点。", "options": [{"label": "记下杨志下一处去向，保留互援之路", "effects": {"路": 2, "义": 1}, "feedback": "你请朱贵若有消息便转达，不追着说服，也不轻易断掉同袍的名字。那些不同路的人，后来也可能成为同一场危难中伸来的手。"}, {"label": "收心练兵，兑现留下时的承诺", "effects": {"势": 2, "义": 1}, "feedback": "你清早便带人练枪，从站稳到轮替一点点教。眼前这群人有了活下来的本事，比谁在席上给你多让半个座位更实在。"}]}, {"ch": 16, "title": "晁盖带来的风", "text": "晁盖等人上山，带着生辰纲的风声，也带着已无退路的人。王伦照旧摆酒，照旧夸本事，话到后来又说山窄粮少。你坐在席边，忽然听见数月前自己的遭遇被换了姓名，原样重来。吴用的目光几次落到你身上，话里有话，像把一柄看不见的刀递到手边。被羞辱过的人最容易认得羞辱，也最容易被别人借着这份认识，推到他们早想让你站的位置。", "options": [{"label": "先问清各方意图，不接受借怒行事", "effects": {"证": 2, "忍": 1}, "feedback": "你当面问吴用，希望自己替他们做什么。他没有立刻回答，晁盖却先说只求安身，你至少逼这场酒席把一部分真话摆了出来。"}, {"label": "主动替晁盖说话，指出粮少只是托词", "effects": {"义": 2, "势": -1}, "feedback": "你说出山中存粮与空屋数目，王伦无从再借此推辞。昔日对你的排斥终于有人公开指认，代价是你再不能退回无事的席位。"}]}, {"ch": 16, "title": "你曾等过的公道", "text": "王伦怒问你是否忘恩，收留你一场，难道还换不来顺从。他说这话时看向众人，仿佛只要给过人一碗饭，便能要求那人从此闭口。你想起高太尉，也想起管营和差拨，忽然发现山寨里竟有同样的声调。你并不因王伦无能就天然有权夺他的命，眼前能争的，是这座山以后究竟靠谁的恐惧维持，又允许谁把规矩讲给所有人听。", "options": [{"label": "请各头领公开议事，先撤独断的权", "effects": {"势": -1, "证": 2}, "feedback": "你要求谁都能在厅中把话说完，杜迁与宋万第一次不得不表态。王伦拒绝议事，将桌案拍得乱响，把最后一点可转圜的空间亲手推走。"}, {"label": "直斥其误寨，准备承担冲突", "effects": {"义": 3, "忍": -2}, "feedback": "你站起身，不再让座次替你规定声音的高低。刀光随争执而起，厅里的每个人都知道，今日不会再靠一轮劝酒收场。"}]}, {"ch": 16, "title": "出手之后的空席", "text": "冲突骤然发生，王伦失去寨主之位，厅中一时只有散落碗盏的声音。有人立刻来劝你坐上首位，说众人都服你的武艺。你望着那把椅子，想到人可以为了活命上山，也可以在看见椅子的瞬间，把曾经受过的委屈解释成自己也该有一次发号施令。晁盖站在桌边没有催，吴用在等你开口。决定谁坐下，也是在决定以后谁有资格叫别人站着。", "options": [{"label": "推举晁盖，先立共议与救急的规矩", "effects": {"义": 2, "退位": 1}, "feedback": "你没有把反抗换成自己的独断，要求重大决断须同议。承诺仍需日后兑现，但它被写在了换主之日，不是酒后可忘的话。"}, {"label": "愿掌练兵，但不占寨主之位", "effects": {"势": 2, "忍": 1}, "feedback": "你把刀收起，接下自己确实会做的事。权柄暂时离你远些，往后能不能靠练兵之职阻住错误，还要看你是否肯再开口。"}]}, {"ch": 16, "title": "夜里擦过的枪", "text": "入夜，厅中已扫净，仿佛一场风暴从未在木地上刮过。你擦枪时，手指忽然用不上力，原来白日一直绷着的不是枪，而是自己。晁盖来坐了一会，没有称你首功，只说山上这么多人，不能因换了一个寨主就认为从此不会犯错。你听了反倒安稳一点。一个肯承认自己也可能错的人，比时时要求别人感恩的人，更像值得一起走一段路的同伴。", "options": [{"label": "请将今日经过记明，不只歌颂胜者", "effects": {"证": 2, "义": 1}, "feedback": "你不愿后来的新人只听一场快意故事。纸上写下争执、逼迫与责任，也写下往后谁若独断，众人仍可照此相问。"}, {"label": "先为死者收殓，让恩怨在此有个交代", "effects": {"义": 2, "忍": 1}, "feedback": "你没有再向倒下的人逞强，安排清理与收殓。白日的决定不会因此变轻，至少不让胜利把最基本的分寸一并烧掉。"}]}, {"ch": 17, "title": "粮仓不是空的", "text": "新任寨主第一件难事不是排座，而是开仓。管粮的说存米不少，账簿却有几笔对不上：有人领两份，有人家眷在山下便不算人口。你以前只管练兵，领到粮便吃，今日看见小孩抱着空袋站在仓门，才知道一条没过问的规矩，也会替某些人把饭碗拿走。晁盖请你主持重验，你可以省事照旧，也可以从今往后让每一袋粮都有能说得清的去处。", "options": [{"label": "按真实口粮重核，把家眷也算进去", "effects": {"义": 2, "钱": -1}, "feedback": "粮袋很快分到原先没有名字的人手里。仓中余粮少了，守军也要重新安排消耗，公平不是把数字写得好看就能不付代价。"}, {"label": "先查重领与冒领，暂缓扩大配给", "effects": {"证": 2, "势": 1}, "feedback": "你把虚领追回，短期守住军粮。仓门外等着的人仍须多等几日，你嘱管粮的把欠下的份额也记明，免得暂缓变成永远不算。"}]}, {"ch": 17, "title": "抢来的货谁来收", "text": "山下一队商货被截，里面有药材，也有沿河小户合凑的布匹。有人说反正已落草，分了就是，替货主计较反倒不像好汉。你拿起一匹粗布，想起贞娘为做一件冬衣曾算了多少日子。劫富济贫几个字若不问货从哪来、送往哪里，很容易让喊得最大声的人先把好东西分光。小喽啰们等着奖赏，你若全部退回，也须回答他们今天吃什么。", "options": [{"label": "核查货主，退民货留权贵赃货", "effects": {"证": 2, "义": 1}, "feedback": "你挨件询问、逐条开单，忙到深夜才分清大半。不是每笔都能立刻查准，但至少小户的布有路拿回，不必同一切权贵财物一并被吞。"}, {"label": "先留下药材，其余折价补偿", "effects": {"钱": -2, "路": 2}, "feedback": "伤兵眼下正缺药，你把急需的留下，按数给出可兑现的补偿。山寨积蓄因此少了一截，你也必须确保字据日后真有人认。"}]}, {"ch": 17, "title": "山下的名字", "text": "一名村老被请到山上，说官军进村搜人，非逼他们报出水泊眼线不可。寨里有人怀疑告密，主张先把村中几户家眷扣住。你看见村老把帽子捏得变形，知道他不是不怕官军，只是怕完官军，还得来怕山上的人。梁山若要活下去，需要山下消息与粮食；若只会逼别人交出忠心，便会让每个小村都夹在两面刀口之间，最后谁也不敢说实话。", "options": [{"label": "给村人撤离法，不扣家眷作保", "effects": {"路": 2, "义": 2}, "feedback": "你安排几处临时住处，把愿走与不愿走分开。消息未必因此更快，村人至少知道，说出害怕不会立刻换来另一道锁。"}, {"label": "派可靠头目查明，暂缩山下联络", "effects": {"证": 2, "忍": 1}, "feedback": "你没有立刻拿谁作替罪羊，先减少暴露。巡查多花了几日，消息也慢下来，眼下少一分便利，换来不把疑心随手变成惩罚。"}]}, {"ch": 17, "title": "夜议一张桌", "text": "仓廒议事结束时，几位头领都累得不想再谈英雄。晁盖笑说从前只想一声号令打出去，如今才知锅里有多少米，也能让人彻夜不眠。你跟着笑了一声，笑完忽然觉得这比豪言更接近一个可以长住的地方。兵器能夺得山寨，不能替人把冬日过完。桌上摊着粮账、药单和家眷名册，那些你从前看作杂务的东西，如今才是山上许多人能不能活过下一年的实处。", "options": [{"label": "立固定轮议，让不同头领都看粮账", "effects": {"证": 2, "势": -1}, "feedback": "你不把清白只寄托在一个好人身上。往后每次分粮，都要有不同的人过目，慢一些，却不轻易把全寨的饭交给一张嘴。"}, {"label": "亲领勤务，把账先理顺再推广", "effects": {"势": 2, "钱": 1}, "feedback": "你把最难的几本收下，连夜重新整理。事情暂时顺起来，你也给自己加上沉重责任，不能把所有人都习惯性留在门外。"}]}, {"ch": 18, "title": "一声熟悉的笑", "text": "寨门外传来大笑，你还没见人，便知道鲁智深来了。和尚僧袍沾着泥，禅杖在肩上，走得比传报的人更快。他看见你，先拍肩，见你站得稳才松口气。武松也在后面，神情寡言，双刀收在鞘中。你们都有后来才添上的风霜，见面时却一时不愿先说苦。原来真有些人不必酒帖、不必座次，只须从门外走进来，你就知道今夜可以不绷着脸坐到天明。", "options": [{"label": "先抱住和尚，好好谢那场救命恩", "effects": {"义": 2, "鲁约": 1}, "feedback": "你终于没再把感激压成一句客气。鲁智深笑得更响，说人还好好的，比谢一万回强，你也跟着笑，笑到眼角有一点发热。"}, {"label": "先请众人进屋热食，再慢慢叙旧", "effects": {"钱": -1, "义": 2}, "feedback": "你把酒菜安排好，不让他们湿着衣裳在风里站。武松帮忙端碗，席还没有正式开，你们已经像一屋做惯事的老伙计。"}]}, {"ch": 18, "title": "他们带来的名字", "text": "酒过几巡，众人谈到一路失散的人。有人仍在逃亡，有人落进牢里，还有人曾与他们把酒，如今只剩托人捎来的一件旧衣。鲁智深不爱说漂亮话，提到救不了的那个人，停了很久。你明白不能叫他替天下人的命都负责，也不能因为责任太大，就从此不再记名字。梁山人数渐多，若只把来山者算作兄弟，没赶到山门的人便会越来越像可随风吹散的空处。", "options": [{"label": "合记失散同袍，派人核实而不妄报生死", "effects": {"路": 2, "义": 1}, "feedback": "你们把确知与不知分开，不用希望顶替消息。名单写出来，便有人轮流去问，那些尚未上山的人终于不只活在酒后一句可惜里。"}, {"label": "先安顿到场者，别再仓促派人冒险", "effects": {"忍": 2, "钱": 1}, "feedback": "你给每人安排床铺与药食，先让脚底有了能站稳的地方。寻找旧人的事没有取消，只暂时压后，等待更稳妥的消息。"}]}, {"ch": 18, "title": "和尚也会累", "text": "散席后，鲁智深独坐在廊下揉脚。你才看见他脚踝肿得厉害，他笑说走多了，不碍事。你以前总把他当能拔树、能劈路的人，以为这样的人不会有真需要别人照顾的一刻。如今他把鞋脱下来，脚底同普通人一样会破，伤口也不会因一声洒家便自动好。你拿来药，他还推，你忽然懂得，兄弟不只是危险时一起往前冲，也该有人在停下时认真说一句，你歇着，这件事我来。", "options": [{"label": "替他换药，暂免他外勤", "effects": {"钱": -1, "义": 2, "养伤": 1}, "feedback": "他嘴里还说小事，最后还是把腿伸出来。你叫人接替几日巡山，伤口终于有了完整结痂的时间，这比又喝一坛表心意更能留下他。"}, {"label": "同他约定有伤必说，尊重他继续当值", "effects": {"义": 1, "忍": 2}, "feedback": "你没把关心变成替他作主，只说不许再拿没事敷衍。和尚点头答应，第二天仍去了寨门，至少会在发作时先找你。"}]}, {"ch": 18, "title": "不必向天许愿", "text": "武松问你往后想怎样。你从前会说洗清罪名、重返军中，如今却先想到一间不用躲人的屋，几张能围坐吃饭的凳。说出口有些不好意思，仿佛英雄不该把盼头说得这样小。武松却说小才难保，大话谁都能喊。鲁智深听了拍腿称是。院中风停，油灯的光静静落在地上，你第一次觉得有些愿望不必向天喊，只须让眼前几个人知道，日后便有人在关键时刻提醒你别忘。", "options": [{"label": "约定将来留一船退路，不人人去争功名", "effects": {"路": 2, "退船": 1}, "feedback": "你们没有发誓同生共死，只说若有人不愿再走，就一起替他找能停下的地方。这约定不响亮，却让未来不只剩一条越走越险的路。"}, {"label": "约定共同练兵，先把山寨守牢", "effects": {"势": 2, "义": 1}, "feedback": "你们从明早的枪阵谈起，谈得具体，也谈得长。眼前的责任没有被远方的愿望冲淡，至于退路，仍须有人往后再提。"}]}, {"ch": 19, "title": "尚未合上的名单", "text": "朱贵拿来山下名单，有故人、有家眷，也有被官府借名搜捕的村民。不同的人藏在不同地方，不能只派一条船、一句话就把所有人接走。你把名单放在灯下，发现某处转递暗号已过期，另一处接头人刚被调走。逃亡最怕的不是走慢，而是以为旧安排仍会等在那里。水面很静，正因为看着没有风浪，你更得在动身前把每一处不知道先写出来。", "options": [{"label": "逐处确认，只在接头落实后动船", "effects": {"证": 2, "路": 2}, "feedback": "核对耽搁了两夜，却发现一处渡口已被盯上。你绕开它，明白谨慎不是把人永远留在原地，而是让出发真正通向另一岸。"}, {"label": "先发先遣船，边走边查缺口", "effects": {"路": 1, "钱": -1}, "feedback": "小舟先入芦苇，你把补充口信交给岸边的人。速度快了，未知也跟着上船，接下来每次停泊都得多问一层来人是谁。"}]}, {"ch": 19, "title": "救一个人的实价", "text": "船老大报出需用的银钱，租船、换衣、药物和沿途吃住，一样也省不了。有头领嫌他要价高，说既是帮梁山，就该讲义气。你看见船老大袖口的补丁，知道让别人白担危险并不比衙门摊派更好。你自己也没有太多可随意花的钱，拿去接人，军中赏钱便要少些。真正的救援不像席上点一个名字，有人应声就完，它要把每个活人的明天一起付出来。", "options": [{"label": "足额备船粮，从个人积蓄先补", "effects": {"钱": -3, "路": 2, "接援": 1}, "feedback": "你把余银分袋交出去，连返程遇险多停几日也算入。船老大不再被迫靠临时索求过路人活命，接应才有了可信的底气。"}, {"label": "请求寨中议拨费用，等待共担", "effects": {"势": 1, "证": 2}, "feedback": "你不把所有责任都揽成私恩，向各头领说明用途。拨款需要几日，名字也须经更多人眼前，你提醒众人不得外泄，这份风险由大家一起负。"}]}, {"ch": 19, "title": "谁来决定离开", "text": "信使问，被接的人若不肯走怎么办。有人舍不得祖屋，有人怕连累你，也有人受过太多假口信，听见新的安排反而退缩。你想起长亭上替贞娘写好的文书，忽然明白不能因为这回确实为了救人，就又把对方只当作须搬走的一件行李。危险要讲清，条件要备好，最后仍得给人说愿意或不愿意的机会。夜色里，船绳轻轻碰着桩，像一声耐心的催促。", "options": [{"label": "用只有彼此知道的细节取信，并留自选之权", "effects": {"家": 2, "暗号": 1}, "feedback": "你交代信使不许催逼，也不许替对方答话。安排因此慢了些，真正上船的人却知道自己走向哪里，不必在获救途中再失一次主意。"}, {"label": "请可信亲友代劝，尽快离开险地", "effects": {"路": 2, "忍": 1}, "feedback": "你让最熟悉的人解释，不由陌生山寨来人开口命令。信使多绕了一程，也多带了几句真话，仍需小心别让劝说变成不准反悔的逼迫。"}]}, {"ch": 19, "title": "芦苇后的灯", "text": "最后一船动身时，你站在岸边直到灯火沉进芦苇。你不能跟每一条船同走，不能保证每个弯口都风平浪静，能做的布置已尽量做完，剩下只能等。等待与从前不同，过去是把结果交给别人发落，如今是知道谁在路上、何时该回、若逾时该去哪里找。朱贵递来热水，没有说一定没事，你因此更愿意把杯子接住。真正的宽慰有时就是有人同你一起承认，眼下还不知道。", "options": [{"label": "安排逾期搜寻与备用岸，轮流等候", "effects": {"钱": -1, "路": 2, "备用岸": 1}, "feedback": "你没有叫所有人彻夜硬撑，而是定下轮值与时辰。船若迟到，不会只换来一群人着急，也有能立刻出发的人和第二处落脚地。"}, {"label": "亲自守完整夜，让别人先歇", "effects": {"义": 2, "忍": 1}, "feedback": "你把斗篷裹紧，坐到天色发灰。没人因你的焦急跟着受冻，身体却实实在在少歇一夜，你明白往后不能只靠自己硬扛。"}]}, {"ch": 20, "title": "椅子开始说话", "text": "山寨人多起来，坐在哪里、谁先说话，渐渐比说了什么更引人注意。有人拿出一套天命的解释，将许多本可商议的事说成早已注定。你看着自己的位置，既不愿为前后争执，也知道身后站着随你出生入死的人，他们分粮、领功、得医，都会被这张椅子影响。一个人可以说自己不在乎名次，却不能用这句话，替所有依赖他的人放弃了被看见的机会。", "options": [{"label": "不争个人座次，要求军需与医疗按需分配", "effects": {"义": 2, "势": -1}, "feedback": "你把最容易变成颜面的争执，转到伤兵真正拿不拿得到药。有人嫌你煞风景，更多人却第一次听见，位置不该决定一条腿值多少药钱。"}, {"label": "接受排序，换取参与机要的资格", "effects": {"势": 2, "忍": 1}, "feedback": "你没有在席间顶撞，换来更多提前知道军令的机会。机会是实在的，也会让你逐渐习惯只有少数人先知道的大门。"}]}, {"ch": 20, "title": "旧伤不合时宜", "text": "宴中有人夸太尉府也未必人人恶劣，招安若成，东京旧事不妨忘一忘。说话的人没有恶意，只觉得劝你看开，是替你打开前程。你握着酒杯，想到那些名字对旁人只是旧事，对受害者却是每天照镜子还能看见的烙印。你不想每场酒都拿自己的苦让人住口，也不愿让别人以为，苦难只要过去一阵，就自然变成了可以替你宽恕的谈资。", "options": [{"label": "平静讲清旧案，拒绝让忘记作前提", "effects": {"证": 2, "忍": 1}, "feedback": "你没有掀席，仍把白虎堂与草场说清。席上有人垂眼，有人换话题，至少下回谈前程时，须知道你不欠太尉府一句算了。"}, {"label": "暂时离席，避免在酒后争论", "effects": {"忍": 2, "路": 1}, "feedback": "你把杯子放下，出门吹了一会风。沉默保住眼前关系，也没有替任何人表示原谅，你须另找清醒时把边界讲明。"}]}, {"ch": 20, "title": "小将求你一句话", "text": "一个年轻头目来问，自己能否随军立功，说只要你点头，上面便会准。他眼中那种急切，你在多年前的校场也见过。你知道出征有机会，也有许多没说给年轻人听的代价。若只劝他惜命，他会觉得你占着位置不肯让路；若轻易推荐，他又可能把你的姓名当成一切都可靠的保证。你没有办法替他活完人生，仍有责任不让自己的名声变成他看不清危险的罩子。", "options": [{"label": "把兵役、抚恤与退出条件讲透，再让他选", "effects": {"证": 2, "义": 1}, "feedback": "他听得比想象中久，最后仍愿去，却先回家安顿母亲。你给出的不是一张免死凭据，而是让他知道哪几件事必须自己问清。"}, {"label": "推荐他，另安排老兵同行照应", "effects": {"势": 2, "义": 1}, "feedback": "你没有堵住年轻人的去路，又托一名稳妥老兵同队。照应不能替代军令，你也把这层责任记下来，不因写了荐语就算完事。"}]}, {"ch": 20, "title": "你想要的体面", "text": "夜里，房中多了一件新袍，说是按头领品次发的。料子好，针脚细，你抚过衣袖，想起东京旧袍曾让自己以为不会有过不去的门。如今同样的体面又被递到手边，你并非不喜欢，只是知道喜欢不能替你辨明它要换走什么。窗外有人练枪，喊声稀稀落落；桌上旧家书的纸角磨白，提醒你还有些盼头，不会因为坐得更前便自动实现。", "options": [{"label": "留旧衣作出行服，把赏钱分备退路", "effects": {"钱": -1, "路": 2}, "feedback": "新袍被收好，没有被你当作从此必须守住的全部身份。衣服能穿也能脱，路若不提前留，临走时再多体面也换不出一只船。"}, {"label": "穿新袍赴会，用现有位置争更实在的安排", "effects": {"势": 2, "忍": 1}, "feedback": "你没有把权位一概推远，决定让它替更具体的人做事。这条路可以走，只须时时记住，衣袖的分量不该把你原先要说的话也压下去。"}]}, {"ch": 21, "title": "赢了以后留下什么", "text": "一场战事暂歇，众人忙着报俘、收兵器、清点战利。你听见桥下还有呼救，两个伤兵被压在倒木后面，身上穿的却不全是梁山衣色。有人说敌军自己来攻，救回来还要耗药。你知道药有限，也知道若只凭衣裳辨哪些呻吟值得停步，日后自己的兄弟落到别人手里，也只能盼对方临时多一点心软。泥地很滑，涨水正逼近桥脚，留给争论的时候不长。", "options": [{"label": "先救人，按伤势而非军籍用药", "effects": {"钱": -2, "义": 2, "救俘": 1}, "feedback": "你把伤重的先抬出，命人收好武器再治疗。有人埋怨药耗得快，救回的人却都清楚，这次活下去并不是因为先喊对了主子的名字。"}, {"label": "先救本部伤兵，再组织余力施救", "effects": {"势": 1, "义": 1}, "feedback": "你让各队先报自己的人数，避免救别队时本队被遗漏。安排更稳，也更慢，余下的时间仍须尽量往那些陌生的呼声赶去。"}]}, {"ch": 21, "title": "功劳簿的空格", "text": "报功的人说桥头这次全赖你突围，想把名字写在首功。你看着那页纸，发现负责拖伤兵的水手只被写成协助，溺水失踪者更没有清楚名字。打得最显眼的人总容易被记住，支撑他站到那里的人却可能被缩成一句辛劳。你也需要声望来推动救人、争取军需，若事事都退，话未必传得上去；可若只取那份便宜，下回谁还愿在最险的桥头替别人撑住背后。", "options": [{"label": "补齐水手与失踪者姓名，首功共记", "effects": {"证": 2, "义": 1}, "feedback": "你花了半日找全名单，最先没被算入的人终于写进正式簿里。功劳分薄，你却更清楚自己这次究竟欠了多少人的手。"}, {"label": "接受主功，承诺把赏银用于伤队", "effects": {"势": 2, "钱": 1}, "feedback": "你用现有规矩争到一笔实在的赏，随后送去药棚。事暂时办成了，仍须把账公开，免得好意又只成别人无法核验的一句话。"}]}, {"ch": 21, "title": "少一人是不是败", "text": "回寨清点时，一个小队还没归来。天色将暗，有人说敌军随时可能反扑，不能为几人拖住全部。你不愿拿大局当堵嘴的石头，也不会假装派所有人出去就叫义气。地图上的一小段沟渠，放到雨夜里会是几个人走不出的黑路。你问清他们最后出现的位置、身上还有多少粮、熟不熟水路，然后才发现，真正困难的并不是愿不愿救，而是如何让救援不再添另一批等救的人。", "options": [{"label": "派小队循最后足迹搜，设明确撤回时辰", "effects": {"钱": -1, "路": 2, "搜援": 1}, "feedback": "你自己守在接应处，命人只循确定路线，不追无证的传言。搜寻因此不是一场谁更敢死的比拼，而有机会把人确实带回来。"}, {"label": "先封稳岸线，等天明有序扩大搜寻", "effects": {"忍": 2, "势": 1}, "feedback": "你把夜里容易误入的渡口封住，让留守者备热食与担架。决定会让你整夜难眠，你仍须对延迟的代价如实负责，不把它说成毫无选择。"}]}, {"ch": 21, "title": "热汤里的沉默", "text": "伤兵坐满临时棚屋，有人疼得说不出话，有人一遍遍问同伴到哪。你走进去时，他们想起身，被你按回。这里不需要再来一次振奋人心的演说，需要的是药有没有熬好，姓名有没有报错，明日家书由谁代写。你替一个右手受伤的人握住碗，看他把汤咽下，忽然觉得一生所学的武艺，若能让此刻多一个人有手端碗，也并非全被命运糟蹋了。", "options": [{"label": "留下写完家书，公开伤亡实数", "effects": {"证": 2, "义": 2}, "feedback": "你没有用胜利遮住损失，也没有把每家的悲喜凑成一句捷报。名字写清后，下一次出战的代价才不容易被人轻轻略过。"}, {"label": "安排轮值照护，自己先去补防", "effects": {"势": 2, "忍": 1}, "feedback": "你把具体的人、药量、交接时辰一一落实，才离开棚屋。关心没有全靠你留在场面上，有人接得住，才更可能持续到后半夜。"}]}, {"ch": 22, "title": "诏书背面的空白", "text": "招安的消息终于传到山上，金色封套被放在席首，许多人眼睛都亮了。有人盼不再让家眷背贼名，有人想重返行伍，也有人只是厌倦每次下山都要先改姓名。你理解这些盼望，自己也曾为一句可以从轻险些落泪。可是诏书讲得多的是忠顺与报效，少的是旧罪如何处理、战后如何安置、谁来保证太尉府不能再把旧账翻出来。那些空白并不耀眼，却可能装下一生。", "options": [{"label": "逐项要求写明赦免、给养和退役", "effects": {"证": 3, "势": -1}, "feedback": "你问得很慢，也问得很难听。有人嫌你不识大体，更多的人却开始发现，他们以为已经得到的承诺，许多尚未真正写进纸里。"}, {"label": "先表愿谈，避免一开始便断路", "effects": {"势": 2, "忍": 1}, "feedback": "你没有把来使赶走，让谈判能继续。门仍开着，但你也承认，愿意谈不等于已经谈妥，更不能要求别人用乐观替代凭据。"}]}, {"ch": 22, "title": "和尚没有举杯", "text": "鲁智深坐着不动，说天下官吏这般，换个印就真能把人变好么。席间有人笑他不懂大局，他脸上的笑顿时没了。你看见这场议论开始从道路之争滑向谁算忠义，仿佛提出担忧的人就是不愿大家好。若你也只选一边喊得更响，下一次商议便会更难有人说真话。你需要做的不是立刻让所有人同意，而是先保住不同意也能留在桌边的资格。", "options": [{"label": "支持反对者自由陈词，不许用忠义压人", "effects": {"义": 2, "势": -1}, "feedback": "你请众人让和尚讲完，再谈如何应对顾虑。厅里冷了一阵，至少不再有人把一句不放心，直接换成对兄弟身份的怀疑。"}, {"label": "私下同和尚谈，避免会中翻脸", "effects": {"忍": 2, "鲁约": 1}, "feedback": "你坐到他旁边，说自己听见了担忧，不会当作酒话。他仍不愿附和，却愿再等你谈出更具体的条件，关系没有被当场折断。"}]}, {"ch": 22, "title": "那几个人的姓名", "text": "使者说高太尉位高事忙，不会再记一名旧教头。你听着，几乎笑出来：受害者记得每一扇门，掌权者不记得，反倒被拿来证明事情已经过去。对方劝你把草场的恩怨放下，好领新官。你不必用一生只为报仇，也没有义务靠忘记来替新盟约作证。桌上的旧案副本并不完整，却仍能提醒在场者，所谓安心，不能只由曾经加害的一方替受害者宣布。", "options": [{"label": "要求旧案列入谈判，不索私刑但求公开确认", "effects": {"证": 2, "势": -1}, "feedback": "你没有开出不可能兑现的报复名单，只要求诬陷不能继续留在正式案卷。使者开始为难，这份为难比轻易保证更接近事实。"}, {"label": "暂搁旧案，先争同袍合法归处", "effects": {"义": 2, "忍": 1}, "feedback": "你把自己的名字从第一件待议中挪开，换来对全体安置的更多谈话。旧案没有因此消失，你也不把这次退让误称为已经得到补偿。"}]}, {"ch": 22, "title": "愿不愿意都该有路", "text": "讨论到最后，最难的不是谁赞成，而是不愿去的人能否不被扣上背弃的名。很多兄弟结识于危难，日后却不必有同样的归宿。有人愿做官，有人想种地，有人只想不再被追捕。你已经见过一次把所有人锁在同一条路上的代价，不愿再以感情作绳。案旁的烛火一根根短下去，来使等着答复，众人也等着有人先说那句会让分歧真正成立的话。", "options": [{"label": "主张自愿去留，并为离队者保留生计", "effects": {"路": 2, "自择": 1}, "feedback": "你承认队伍可能因此不再整齐，也可能失去几分声势。可人的去向终于不全由别人的大愿决定，能离开，留下才更像真正愿意。"}, {"label": "主张暂时共同进退，待条件齐再分流", "effects": {"势": 2, "忍": 1}, "feedback": "你希望先借团结谈出更多保障，分流被推后。这有现实用处，也有期限风险，你在纸上补了复议时辰，不让暂时变成永无后来。"}]}, {"ch": 23, "title": "天王没有回来", "text": "晁盖中箭后的消息传回山寨，许多人到最后仍不肯相信。你站在祭堂外，听见有人争论遗命，有人议论下一任，却先想到仓廒里那句不能因换了寨主就认定不会犯错。一个人的死来不及只属于哀悼，很快就会被活人拿去替未来作证。你不愿在此时争权，也知道若把全部判断都交给悲痛，明日又会有人替你解释谁才是最该顺从的道路。", "options": [{"label": "先核实遗命与当场见证，不让传言代替", "effects": {"证": 2, "势": -1}, "feedback": "你请见过的人各自写下，不相互套词。许多含糊处仍未立刻清楚，至少没有一句口耳相传的话可以毫无阻碍地管住所有人。"}, {"label": "先办丧事，让兄弟能好好送别", "effects": {"义": 2, "忍": 1}, "feedback": "你把香烛、衣物和来吊人的次序安排妥当。权位的争执仍在门外，没有被你否认，却至少给悲伤留了一晚不用急着站队的空间。"}]}, {"ch": 23, "title": "忠义二字的重量", "text": "灵前有人说要报仇，也有人说更须完成天王未竟之志。你听着这些大字眼，想起晁盖平日其实也会为一筐坏米发愁，为一名伤兵少药而恼。若只把人留成几句供后人使用的口号，他曾经怎样对待具体的人，反而最容易被忘。你擦去空椅上的雨水，看见木扶手磨出的亮痕，那里曾放过一只活人的手，不是从一开始就为了让别人借他的名字说话。", "options": [{"label": "记下平日做事与过失，不只写英名", "effects": {"证": 2, "义": 1}, "feedback": "祭文少了些整齐的夸赞，多了会让相识者点头的细节。尊敬不必建立在从未犯错的假像上，认真记住一个人，本就包括他怎样学会负责。"}, {"label": "召集老部照顾遗属，先兑现身后承诺", "effects": {"钱": -2, "义": 2}, "feedback": "你把抚恤从仪式里拿出来，落到一户户家门。不能让壮烈只属于死者，往后的饭却全留给活着的亲人自己想办法。"}]}, {"ch": 23, "title": "枪穗与一坛酒", "text": "鲁智深提了一坛酒过来，说本以为上了这座山，就不会再看熟人一个个少。他没有哭，话却说到一半停下。你把酒碗放在空椅边，没有说他一定还在看着，也没有用总会好来堵住这份沉默。你们经历太多，最怕的已不是有人在眼前死去，而是每次都被要求立即把悲痛炼成下一次出发的勇气，仿佛只要继续往前，便不用认真问为何一再失去。", "options": [{"label": "同他重提退船约定，承认可以停下", "effects": {"路": 2, "退船": 1}, "feedback": "他望了你很久，终于说若有那天，别再等到谁先倒了才走。这句话没有让今夜不痛，却把将来的门又推开了一点。"}, {"label": "答应先护现有兄弟，把悲痛变成准备", "effects": {"义": 2, "养伤": 1}, "feedback": "你们查了药棚和值夜名册，安排受伤者歇息。不是每份难过都必须立刻有用，但愿意做一点具体的事，能让手不再一直发抖。"}]}, {"ch": 23, "title": "椅子换了名字", "text": "新一轮议事照常开始，空着的主位终会有人坐，山寨不会为了谁永远停在同一天。你穿过熟悉的门，忽然明白自己也有一天会被人概括成一个名次、一场战事、一句性情温厚或忍无可忍。那都不足以写完一个人。你想留下些什么，不再只是枪法或一次出手的痛快，还想让后来有人能够不必重走你的每一条窄路，便知道自己也有资格问一句，除此之外还有没有别的走法。", "options": [{"label": "请将撤离与伤退制度写入军议", "effects": {"路": 2, "证": 1}, "feedback": "规矩里第一次清楚写下，何种伤情应退、谁负责家眷、去留如何自选。纸不等于保证，却比临时求情多一个能援引的起点。"}, {"label": "接下更重军职，希望从内部护人", "effects": {"势": 2, "义": 1}, "feedback": "你承担更多出战与调度，不再只作旁观者。位置能替你争到人手，也会把你绑得更紧，日后说走时需要付出的便更多。"}]}, {"ch": 24, "title": "赞成之前先问什么", "text": "来使再上山时，带来比上一回更完整的条件，也带来催促。许多头领急于结束悬而未决的日子，望着你时，眼里既有期待，也有一点不耐。你知道自己不可能替所有人选出一条从此不受伤的路，天下也没有这样现成的路。你能做的是把尚未解决的缺口说清，再决定自己愿为哪种不确定性承担后果。风掠过案上的纸角，金色封套被吹起一点，下面仍是普通人的墨与字。", "options": [{"label": "再核给养、赦免名单与退伤条款", "effects": {"证": 2, "势": -1}, "feedback": "你逐行核对，发现一处家眷保障仍只在口头。谈判因此又慢下来，催促却不再能被你误认成条件真的已经齐全。"}, {"label": "承认条件已改善，先组织自愿者", "effects": {"势": 2, "忍": 1}, "feedback": "你不因曾受害就否认眼前实有变化，愿意者开始登记。你同时提醒，没有登记的人也不因此成了欠大家一句解释的异类。"}]}, {"ch": 24, "title": "留下的人也要吃饭", "text": "有人把拒绝招安的理由说得豪壮，说一辈子留山便是。朱贵却问，官军封锁水路后，粮从哪里来，家眷怎样过冬。大厅里静了下来。反抗可以是正当的，反抗者同样不能只靠勇气喂饱身后的人。你不愿用现实把理想一棍打死，也不愿让理想免除筹粮、撤离与谈判的责任。桌上的地图在两条水道间留着一片空白，那正是选择之后，仍须有人认真填上的日子。", "options": [{"label": "为留山者拟商路、村约与撤离线", "effects": {"路": 2, "钱": -1}, "feedback": "你把可能断掉的粮路逐条标出，议定不强征村粮。留山不再只是席上一句不服，也开始有能让孩子撑过冬天的办法。"}, {"label": "主张缩小常备军，减少继续对抗的负担", "effects": {"势": 1, "证": 2}, "feedback": "你承认山寨规模不能永远扩大，让愿散的家户先自行安置。声势会小一些，留下的人却不必为一种必须壮大的想像不断消耗。"}]}, {"ch": 24, "title": "离开不等于忘记", "text": "想退的人里有伤兵，也有已带家眷的人，他们来问你能否先走。有人怕日后被说不够义气，连准备好的行李都不敢收。你想起东京长亭，自己也曾拿一种为了别人好的说法替妻子决定；如今若又用兄弟名分要求所有人同行，区别只在所用的词更响亮。你不是不舍得，而是不愿等到葬礼上才说早知道该劝他停下。门外有人扶着伤腿，已站得太久。", "options": [{"label": "公开支持自愿退出，并帮他们找生计", "effects": {"路": 2, "自择": 1}, "feedback": "你替第一个人把包袱提到门口，才有人敢接着说自己也想走。离别让队伍不再整齐，却让人第一次不必以受重伤作唯一的退场凭据。"}, {"label": "要求先完成共同防务，再分批离队", "effects": {"势": 2, "忍": 1}, "feedback": "你把期限定在纸上，不让待办无限延伸。留守者因此多几分保障，想走的人也知道哪天可以真正来领自己的归程。"}]}, {"ch": 24, "title": "该把脚落在哪里", "text": "议事最后轮到你亲自答复。你不能再只靠提出问题留在所有道路之间，朝廷、山寨、远行各有代价。你有旧案，有同袍，有还未兑现的家书，也有一身不愿全耗在追逐某个许可上的武艺。你曾经不敢离开一间自己修好的屋，如今却能站在三条路前，清楚知道没有一条替你免去责任。不同的是，这一次出门，不必再等别人递来一份你无法拒绝的召帖。", "options": [{"label": "随自愿者接受招安，亲自盯住承诺", "effects": {"朝路": 1, "势": 2}, "feedback": "你在名册上写下自己，约定违背给养与退役条款便再争。选择官道并不等于宽恕旧恶，你将以自己的处境继续检验这份盟约。"}, {"label": "留在山寨，守住共同生活与去留自由", "effects": {"山路": 1, "义": 2}, "feedback": "你把名字留在山上，答应不给村人强摊粮草，也不拦自愿离开者。拒绝招安至此有了日常责任，不能只靠一句不信朝廷活下去。"}, {"label": "退出权力与征战，先把身边人送到安稳处", "effects": {"归路": 1, "路": 2}, "feedback": "你没有要求大家同你走，先交接自己的军务。退下来少了头衔与军粮，往后生活要自己筹划，换来的是终于能把人的去向放在功名之前。"}]}, {"ch": 25, "title": "名字写在前还是后", "text": "新的道路刚开始，第一件事仍是点名。出征者要编队，留山者要分巡，离队者也须知道谁同船谁改走陆路。你看着同一张纸上挤在一起的姓名，明白无论走哪条路，管理都可能把人写成便于挪动的数目。一个人多了一条伤腿，母亲多了一次病，纸面上的日程便会忽然不合用。若只责怪个人拖累大局，每次整齐都会是某些人默默掉队换来的。", "options": [{"label": "逐人问伤情与家属，按实情重新编排", "effects": {"证": 2, "义": 1}, "feedback": "名单变得更杂，却更接近实际。你知道谁不能久行、谁需要同行照料，遇到变故便不必又临时猜哪几个名字该先被放弃。"}, {"label": "按现有队伍推进，另设机动接应", "effects": {"势": 2, "路": 1}, "feedback": "大队保持了原定时辰，机动人手承担更重压力。你把谁负责接应也写上纸，不让照顾落后者永远只是一句交给后面的人。"}]}, {"ch": 25, "title": "军令之外的热饭", "text": "营火烧起来，有人还在修车，有人在等找回的药袋。掌事说过了饭时便不再开锅，免得所有人都来讨特别照顾。你看见一个年轻人用冷水泡饼，手指冻得弯不过来，原来他刚替别人推车到岸边。公平若只按一口钟响过没有来算，最肯多做事的人便可能总错过热饭。可另开灶也要柴米、要人守，不能每回都靠你恰巧路过。", "options": [{"label": "设轮值留饭，晚归者也有明确份额", "effects": {"钱": -1, "义": 2}, "feedback": "你让后勤按实际出勤留下一锅，不是给谁私下加菜。规则多了一条，巡夜与收尾的人才不必在做完事之后再靠求人吃热的。"}, {"label": "先分自己的热饭，明日再议制度", "effects": {"钱": -1, "家": 1}, "feedback": "你把碗递过去，年轻人吃得很急。眼下这一顿解决了，明日若你不在，仍须有人记得把问题从一只碗推到所有晚归者身上。"}]}, {"ch": 25, "title": "伤退者的纸条", "text": "一名伤者说要退，医者认定他不宜再走，队正却嫌手续不全。他的姓名在几处不同册里，每处都要另一个地方先签字。你见过人被一纸供词送进牢，如今又看见人被几张看似合理的文书留在不该继续受伤的路上。没有人承认自己要害他，人人都说不敢擅自作主。你需要的不只是替这一个人通融，还要问清，规则里究竟是谁该对最后活着的人负责。", "options": [{"label": "据医嘱直接办理，自己承担签押责任", "effects": {"势": -1, "义": 2, "退伤": 1}, "feedback": "你签下姓名，要求后续有异议找你，不许再扣病人。这个决定会被追责，你仍知道，拿一个人的身体等手续齐全，不是没有作决定。"}, {"label": "找齐医者与管事共签，把口子正式打开", "effects": {"证": 2, "路": 1}, "feedback": "你把各处人请到同一张桌前，逼他们当面说缺哪一步。手续终于办完，耗了不少力气，也留下后来伤者可以照着走的先例。"}]}, {"ch": 25, "title": "同桌不必同愿", "text": "夜里几人围火，有人谈官爵，有人谈一片可种的地，还有人只想找回失散的姐姐。你听着，没有再把这些愿望按大小排高低。自己走到今日，最怕的就是别人替你宣告什么才算不枉一生。火边那个始终沉默的人抬头问你，若终于不用再证明自己是好汉，会先做什么。你一时答不上来，过了一会，才想到也许会先把一顿饭从热吃到凉，不必听见门响就立即起身。", "options": [{"label": "把各人愿望记作归程依据，不当成笑话", "effects": {"路": 2, "家": 1}, "feedback": "你请每人留一个可信的落脚处与联系人。日后分手便不只是祝保重，也有知道该往哪里寻人的实在凭据。"}, {"label": "鼓励各自保留，不将私人生活纳入名册", "effects": {"忍": 2, "义": 1}, "feedback": "你没有因为关心就要求知道所有秘密。留下的人愿说便说，想藏的也能藏，人与人之间仍有不需向头领交代的余地。"}]}, {"ch": 26, "title": "雨里另一个家", "text": "你们行到水乡，雨将街巷洗得发亮，河边有逃难的人挤在屋檐下。远处战火或追捕的消息把这里的人也逼上路，他们不认识你，不知道你的旧案，也未必愿相信任何持刀带枪的队伍。一个妇人抱着孩子，反复问船能到哪岸，你忽然想起自己的家人也曾需要听到一个确切地点。你可以继续原定日程，也可以在这里多停，代价是粮食、时间和被别处责问的风险。", "options": [{"label": "停船分粮，先帮最急的家户过水", "effects": {"钱": -2, "义": 2, "渡援": 1}, "feedback": "船多走两趟，米袋轻了一些。你没有许诺包下他们往后的生活，至少这一个有涨水危险的夜晚，有几家人不必抱着孩子蹲在岸边。"}, {"label": "先告知可靠避难处，保持主队行程", "effects": {"路": 2, "忍": 1}, "feedback": "你把能走的路讲清，请熟悉水道的人带一程。主队没有停太久，留下的人仍需自己接着走，你不把指路夸成已替他们渡过全部难处。"}]}, {"ch": 26, "title": "一处陌生的陷阱", "text": "接应者指的近路穿过窄桥，桥那头停着几辆空车，说是可借来搬伤者。你本想即刻点头，却发现车辙从桥边开始，后面并没有正常来路。有人催你别疑心太重，赶时间最要紧。你从前也怕自己多问会显得不合群，最后在白虎堂里连一句解释都没来得及说完。如今多看一眼不是怀疑天下人，而是承认好意同样可以被冒用，尤其在大家最急着相信的时候。", "options": [{"label": "先派熟路者试桥，不让大队一起拥入", "effects": {"证": 2, "路": 1}, "feedback": "探路发现桥侧伏着拦路的人，你们改走上游。多走一段比进了陷阱再怪谁不够英勇便宜得多，谨慎终于替身后的人省下一场伤。"}, {"label": "与来人核对接头细节，再少量分批过", "effects": {"证": 1, "忍": 2}, "feedback": "你没有全盘否定，却把无法答清的地方停下来问。对方露出破绽，近路被放弃，一句听着顺耳的保证没能再替你决定脚步。"}]}, {"ch": 26, "title": "被征走的船", "text": "官差到岸边要征所有民船，拿着一张写不清归还日期的牒文。船户不敢反抗，只问收了船，家中靠什么吃饭。你此时无论身份如何，都清楚自己可以选择不管，继续完成手上的任务；也可以开口，立刻给队伍添上新的交涉。你望着一名老船户掌上深深的绳痕，忽然想到，天下有多少被称作顺利推进的事，只是因为承受代价的人没有名字写在捷报里。", "options": [{"label": "要求留生活船，并开可追索的征用凭据", "effects": {"证": 2, "义": 1}, "feedback": "你没有靠一声怒喝便假装取消征用，而是让时间、补偿与船号写明。船户仍要受损，至少不必拿全家生计换一张谁都能推开的空纸。"}, {"label": "先替最穷几户付租金，减少眼前损失", "effects": {"钱": -2, "家": 1}, "feedback": "银钱不够补所有人，你按依船为生的家户先给。不能解决的部分仍在，你把它说清，也不拿几袋银钱替整件事画上圆满的句号。"}]}, {"ch": 26, "title": "雨停时不见的人", "text": "天将亮时，人数少了三个。传令者说他们可能去了市集，队伍若等太久，会错过水位适合的一段河道。你立刻想到夜里那几辆空车，也想到人不是只有遇敌才会不见，照顾病人、迷了路、被拦问，都能让一名普通同伴从整齐数字里突然掉出去。你不能每次都用最坏猜想拖住大家，也不能每次都用大约没事替尚未出现的人结账。雨水顺着帽檐落下，点名的纸开始洇墨。", "options": [{"label": "按最后职责找人，派小队留守而主队缓行", "effects": {"路": 2, "搜援": 1}, "feedback": "你把搜寻与行军拆开安排，既不全队停在险地，也不直接放弃。留下的几人有粮、有信号、有该回的地点，等待不再只有一句尽力。"}, {"label": "亲自回寻，请副手依预案带队", "effects": {"势": -1, "义": 2}, "feedback": "你把明确路线交给副手，带两人折返。亲去未必永远最好，却在眼下让熟悉细节的人能尽快找到那几个仍不知道大家已走的同伴。"}]}, {"ch": 27, "title": "桥头的旧伤", "text": "鲁智深的旧伤在连日雨路里发作，他仍不肯放下禅杖，说自己走得动。你看见他上桥时脚下一顿，便知这句话已比事实更硬。武松在旁想扶，又怕他觉得被当作废人，只伸手接了行李。你们都是习惯在别人面前能扛的人，最难的反而是承认身体有极限。桥后追索与军令都在催，若照旧只靠意气赶路，下一次停下也许就不再能由本人选择。", "options": [{"label": "停步验伤，用车代步不让他再硬走", "effects": {"钱": -2, "义": 2, "养伤": 1}, "feedback": "和尚先骂了两句，最终坐上车。你没有叫他从此什么都不能做，只把继续用旧伤换体面的那条路暂时拦住，让身体有机会赶上你们。"}, {"label": "分担行装、缩短一日路程，让他保留自主", "effects": {"路": 2, "忍": 1}, "feedback": "你们没有当众揭他的短，悄悄把最重的东西接走。速度慢了，仍需留意他是否真的能走，不能把尊重当成不再过问的借口。"}]}, {"ch": 27, "title": "武松把刀放下", "text": "武松查车轴时，把双刀搁在石栏，掌心磨出一道新伤。他说自己平生最不怕拼命，如今却愈来愈怕拼完以后，回头找不到熟人。你听着，没有拿豪情替他遮掩。一个人敢于说害怕，未必比挥刀更容易。你们曾因刀枪相识，接下来是否还能靠别的东西留在彼此身边，取决于此时有没有人认真听见这句话，而不是笑着说兄弟怎能长他人志气。", "options": [{"label": "同他确认不再争无谓先锋，先保撤离", "effects": {"义": 2, "救友": 1}, "feedback": "你们把话说在上阵之前，不等谁重伤才追悔。少一次最前排的功，不会让过去的勇敢变假，倒可能让下一顿饭仍有熟悉的人在。"}, {"label": "请他负责后卫，用信任换更稳的队形", "effects": {"势": 2, "路": 1}, "feedback": "你没有让他从危险中凭空消失，而是把更需判断的守后交给他。命令里写清可退时辰，不把后卫悄悄变成必须最后死的人。"}]}, {"ch": 27, "title": "装不下所有人的车", "text": "车只剩一辆，重伤者与粮袋都要靠它过桥。有人提议把一名昏沉的人留在庙里，说给足干粮，也算照顾。你看见医者摇头，知道他连自己喝水都做不到。眼前的难处是真的，最轻易的说法却总让最不能反对的人承担。你盘算人数、绳索与可弃之物，发现把自己的装备与部分粮袋卸掉，能腾出位置，但后面几日的路便会更饿、更难走。", "options": [{"label": "弃重装备、分背粮，先带走不能自理的人", "effects": {"钱": -2, "义": 3, "重援": 1}, "feedback": "车上终于多出一处能躺的地方，你们肩上的担更重。没有人因此不用付代价，只是这次不再把代价全压给最无力说话的那一个。"}, {"label": "让强健者分组轮抬，不轻弃后续粮食", "effects": {"路": 2, "忍": 1}, "feedback": "你把轮换时辰排细，自己也进第一组。走得很慢，粮袋保住了，轮抬的人却更疲惫，接下来必须及时歇息而非继续靠硬撑补进度。"}]}, {"ch": 27, "title": "过桥后的点名", "text": "最后一人过桥时，天已放晴。你没有立刻松口气，拿出名单，从第一行念到最后一行，确认不是只把最后那辆车带过来，前面的人却已经散了。有人嫌你念得慢，念到自己的名字时又不由答得很响。你忽然明白，那声到不只是服从，也是在告诉一个愿意数清的人，自己仍在这里。桥下水声很大，你把听不清的名字又叫一次，不肯用差不多替这次过桥结尾。", "options": [{"label": "各队互认人数与伤情，留明后续照护", "effects": {"证": 2, "义": 1}, "feedback": "点名结束后，你还让同伴认人，免得纸对上了，实人却被错认。热食和药随后送来，这场救援才不只停在把人从桥这头搬到那头。"}, {"label": "先全员休息，自己与医者逐帐复核", "effects": {"忍": 2, "家": 1}, "feedback": "你没有让疲惫的人继续站着受检，带医者一处处走。确认得更慢，答声也低，却能看清谁只是嘴上说没事，伤口仍在渗。"}]}, {"ch": 28, "title": "不必再跪的案卷", "text": "一路辗转，终于有一位愿听旧案的地方官。桌上不是太尉府的宝刀，而是你留下的供词、荐书与差牌。证据完整与否，取决于早些年那些看似拖慢脚步的小决定；眼下不会因为你立过功，就自动把没有保留的纸重新变出来。官员翻看时，你站着，没有被要求先跪。这个小小差别让你几乎说不出话，过去等得太久的事，真到面前反而不再像自己想过的那场痛快。", "options": [{"label": "请求按证据重审，不把名望当证据", "effects": {"证": 2, "忍": 1}, "feedback": "你把确知与推断分开，不替空缺编词。官员认可你的克制，仍要按存档追索，这过程未必快，却不必靠制造另一份假话来替真事伸冤。"}, {"label": "先为受牵连者销除追索，再议个人清白", "effects": {"义": 2, "路": 1}, "feedback": "你把其他人的名字往前放，请官署先给可公开行走的凭据。自己的心结没有立刻解开，身后的活人却能少躲一处关卡。"}]}, {"ch": 28, "title": "道歉由谁来说", "text": "一名旧日办事人被召来，他见你如今身份不同，满口称当年受蒙蔽，早已悔恨。你分不清几分真，几分只因形势变了。身边有人催你宽恕，说人既肯低头，再纠缠显得不够大度。你忽然厌倦极了，为何做坏事时他只须听上头命令，轮到自己受害，却还要负责把原谅做得体面。你可以不追打，也可以不接受，那都应由你亲口决定，而不是被席间的和气提前写好。", "options": [{"label": "拒绝代替一切受害者宽恕，要求公开作证", "effects": {"证": 2, "义": 1}, "feedback": "你不把羞辱还给他的家人，也不轻轻说算了。能做的补救先做，是否原谅另议，这两件事终于不必被强绑在同一句漂亮话里。"}, {"label": "不再与其私谈，将责任交给正式审理", "effects": {"忍": 2, "路": 1}, "feedback": "你请人按程序记录，自己离开桌边。有些账不需要每次都由受害者重新讲到流血，交出去不等于忘记，也可以是开始拿回余生。"}]}, {"ch": 28, "title": "一枚断簪的分量", "text": "你把旧物从夹层取出，放在案边。它曾属于一段普通日子，后来被卷进阴谋、逃亡、通信和等候，如今又要被人用证物两字概括。官员询问来历，你一句句说，发现自己记得的不只是恶人做了什么，还记得那天她怎样按住衣袖，怎样先问你有没有被灌下不干净的酒。真正的损失不能全写进判词，判词能做的也许只是承认，那些事确实发生，不该被当作你想得太多。", "options": [{"label": "讲清她自己的抵抗，不只讲自己的冤", "effects": {"家": 2, "证": 1}, "feedback": "记录多了一个不是附属在教头名后的活人。她的判断、求援与拒绝，也被放进这段经过，不必永远只以受害二字被记住。"}, {"label": "请将私人细节封存，只公开必要事实", "effects": {"忍": 2, "家": 1}, "feedback": "你为隐私留了一道门，公案不必吞尽一生最细小的伤处。案卷可以证明罪责，却不因此自动拥有所有记忆的处置权。"}]}, {"ch": 28, "title": "清白是不是归途", "text": "离开衙署时，天色很亮。无论旧案能进到哪一步，你都知道东京不会因为几行新的字便完全变回从前，昔日同僚已散，房舍易主，旧门槛上的磨痕也不再为你保留。你曾以为洗去罪名就能把被夺走的一切找回来，走到今天才明白，承认公道与重建生活是两件都重要、却彼此不能代替的事。你握着案边带出的回执，先辨认的不是回京方向，而是谁还在门外等你。", "options": [{"label": "把回执留底，转身认真安排未来生计", "effects": {"路": 2, "家": 1}, "feedback": "你没有将案卷扔掉，也没有继续让它占据每个清晨。旧事有了能查的去处，明日的米、药、住处，开始获得与你的愤怒同样郑重的位置。"}, {"label": "保留复查权，继续走完未完成的申诉", "effects": {"证": 2, "势": 1}, "feedback": "你不肯让一份回执就替多年等待作结，列出后续应查事项。你也约束自己不再日日守门，把追索分成有期限、有凭据的步骤。"}]}, {"ch": 29, "title": "终于能坐下的一顿饭", "text": "旅舍窗临水，伙计端来热饭时，先问要几副碗筷。这个问题让你停了一下，人数在这些年里不知改过多少回，竟比问头衔更能叫人清醒。你报出眼下确在的人数，又请留一点给晚到者。桌上没有庆功牌，也没有催赴的军帖，只是一盘青菜、一碗鱼汤和几张等人落座的凳。你一生有许多饭没有好好吃完，此刻筷子握在手里，先想到的却是这顿饭不该也被新的宏愿匆忙打断。", "options": [{"label": "等同伴洗好手，一起开饭", "effects": {"家": 2, "义": 1}, "feedback": "热气淡了一点，众人终于坐齐。你们没有谈必须再成什么大事，先把一顿饭吃完，这件从前觉得寻常的事，如今竟像一种认真争来的能力。"}, {"label": "给赶路的人留足饭，自己先歇息", "effects": {"忍": 2, "家": 1}, "feedback": "你把份额讲清，回房卸下沉重外衣。照顾同伴不必每次都靠自己最后才吃，肯承认疲惫，也是往后能继续相伴的一部分。"}]}, {"ch": 29, "title": "还算不算有用", "text": "一个少年认出你的枪法，兴奋地求教，说听过许多关于林教头的故事。他讲得豪气，里面的你没有踌躇、没有哭，也不曾为几袋粮费尽心思。你并不怪他，少年总需要一个看起来能打穿世道的人。可是若教给他的只有怎样把枪刺得更快，他也许仍会在另一座白虎堂前，带着好刀等一份不该信的召令。你看着他亮起来的眼睛，想把自己真正学会的那一点也放进第一课。", "options": [{"label": "先教辨路与护人，再教枪法", "effects": {"义": 2, "证": 1}, "feedback": "少年起初有些失望，听到野猪林的绳索时又静下来。你没有拿惨事吓退他，只让本领从一开始就不只属于击倒别人。"}, {"label": "先试心性与耐性，暂不轻许师徒名分", "effects": {"忍": 2, "势": 1}, "feedback": "你让他连练数日基础，问为何学枪、愿不愿听不威风的话。名分少许多热闹，却也少一次让年轻人误以为从此有人能替他活完险路。"}]}, {"ch": 29, "title": "一封不用绕路的信", "text": "你提笔写信，许久才发觉这回不必把每个名字都拆开藏，不必借冷暖猜哪句才是平安。可手仍会下意识停在地址前，逃亡练出的习惯，不会因为暂时安稳就听话消失。窗外有船靠岸，橹声慢得让人心慌，你告诉自己不是每一次脚步都来拿人，也不是每一次门响都必须先藏刀。普通日子若重新来到，也要一点点学着接住，不能要求自己立刻像从未受伤的人一样生活。", "options": [{"label": "坦白仍会害怕，请亲近者帮自己慢慢适应", "effects": {"家": 2, "忍": 1}, "feedback": "你没有再用没事顶回关心，写下会惊醒、会迟疑，也写下正学着不把所有人推远。信里因此有了一个比传说更真实的你。"}, {"label": "把不安记在私页，按计划建立规律作息", "effects": {"路": 2, "忍": 1}, "feedback": "你给自己留一处不必公开的纸页，定下吃饭、练枪与休息时辰。规矩不再只由官府与军令写，也能被自己拿来一点点养回生活。"}]}, {"ch": 29, "title": "人能走到哪里算哪里", "text": "再往前，几条归路已渐渐清楚：仍有人愿你担军职，有人邀你守山，也有人在一处不会因旧案而轻易问罪的地方租好小屋。每条路都与此前的付出相连，不会因今天说想团圆，便让来不及保护的人重新回来。你终于不再要求结局必须证明一生的苦全都有价值，有些苦本来就不该发生，余下日子仍值得被好好过。你把可行的安排一项项看完，先问自己还能替谁负责，也能否给自己留一份。", "options": [{"label": "清点可用退路与同伴意愿，准备最后安置", "effects": {"路": 2, "家": 1}, "feedback": "你把能走的同不能走的分开，不用一句都有办法蒙混。几条真正存在的归路被确认，未能挽回之处也被诚实留下，不再用想像填平。"}, {"label": "核对军职与山中责任，办完交接再离开", "effects": {"势": 2, "证": 1}, "feedback": "你不想让自己的归隐变成别人突然多出的烂摊子，把人手、粮账和未竟事务写清。告别因此晚一些，却不必让后来者替你补一片空白。"}]}, {"ch": 30, "title": "这次不赶谁上船", "text": "候船的人陆续到了，行李比从前少，药包却比从前多。有人要往北，有人要顺流南下，你们不可能再像刚上山时那样，把所有人留在一张长桌旁。你看着各自说好的去向，没有将不舍变成命令。能同船是幸运，不同船也不等于背弃。河面映着灯，你给每个包袱系好不易认错的记号，像多年以前贞娘给一双鞋缝进银钱，把真正的关心藏在能用上的细处。", "options": [{"label": "逐个确认联系人与下次报平安的方法", "effects": {"路": 2, "信路": 1}, "feedback": "这回的通信不必只绕着追兵走，仍值得认真安排。你们约下明确时节，不把保持联络全寄托在有缘再会四个无处追索的字上。"}, {"label": "尊重各自隐姓安排，不要求留下地址", "effects": {"忍": 2, "义": 1}, "feedback": "有人愿说，有人需要彻底从旧名里离开。你没有因曾救过他，就要求掌握他的余生，离别也因此少一层难以拒绝的人情债。"}]}, {"ch": 30, "title": "团圆不能代写", "text": "你终于能将家中消息同这些年的安排放在一起看。有些回音来自被接到安全处的亲人，有些来自保留旧物的长辈，另一些只剩没有等到回信的地址。你没有权利用一场盛大的重逢，把各人独自撑过的年月全说成值得；也没有必要因未能得到最圆满的一种，就否认身旁仍可共同生活的人。你轻轻摸了摸那枚旧枪穗，知道该怀念的可以怀念，该道歉的仍须道歉，该从今日重建的也只能从今日开始。", "options": [{"label": "把选择与去向当面讲清，不再替亲近者决定", "effects": {"家": 2, "自择": 1}, "feedback": "你一一听完，不急着反驳。有些答复让你失落，有些让你松口气，但这一回，船要载的是愿意同行的人，不是被善意安排好的行李。"}, {"label": "先安顿需要照顾的人，其他愿望稍后再谈", "effects": {"钱": -1, "义": 2}, "feedback": "你把床铺与药物安排妥，确认没人为了说客气话把痛忍过去。情感不必一次讲完，能在明天还坐在身边，才有继续说的地方。"}]}, {"ch": 30, "title": "和尚放下的禅杖", "text": "鲁智深坐在船边，看见你还在数包袱，笑你比管营更爱点名。你说至少这回数的不是少几袋粮该罚谁，他听完大笑，笑了一阵又咳。你伸手接过禅杖，他没有再争着自己扛。武松在另一头修船绳，偶尔插一句话，声音比席间安静。你们都没有变回少年，却还能在这些不威风的事上互相搭一把，这种相伴比一同冲阵少许多传奇，也可能更值得留下。", "options": [{"label": "同意不再以身涉险，轮流照顾彼此", "effects": {"义": 2, "救友": 1}, "feedback": "你们没有发永不生病的空誓，只约定难受就说，不再等到倒下才让别人知道。未来仍有衰老与别离，能提前承认，已是另一种勇气。"}, {"label": "让他们保留所长，自己接手繁琐日常", "effects": {"家": 2, "忍": 1}, "feedback": "你把买米、问医、修屋的事接过来，知道自己也会有做不动的一天。分工能变，谁也不必因放下兵器就觉得再没有被需要的理由。"}]}, {"ch": 30, "title": "最后一段水路", "text": "船老大问可以起行没有，你抬头看两岸。曾经每次出发，都是有人命你去、逼你去、赶你离开；后来也有自己选的路，却总急着证明那选择没有错。到今天你不再需要把一生交给某句评语，别人可以说英雄落草，也可以说忍到尽处，只有自己知道其中还有一双鞋、一顿热饭、几封不知是否送到的信。船桨一响，你先把行李放稳，终于没有把目光一直留在无法回去的岸。", "options": [{"label": "接受道路的实际代价，不再追逐人人认可", "effects": {"忍": 2, "路": 1}, "feedback": "你将还未得到的称赞放下，余生反而轻了一些。不是从此不介意，只是知道不能再用所有明天，去换一个未必愿意公道看你的人的一句满意。"}, {"label": "保留姓名与经历，让后来人知道别的选择", "effects": {"证": 2, "义": 1}, "feedback": "你不再只藏身，也不把自己写成从未犹豫的人。别人若从这些经过里看见可以早些求援、早些护人，故事便多了一点不必再用命验证的用处。"}]}, {"ch": 31, "title": "不是传说的早晨", "text": "多年后，你仍会比天亮早醒。窗外有鸟，也有远处行人的声音，你不再每次都先摸枪，偶尔能继续躺一会，看光从窗纸一点点亮起来。身上的旧伤在雨前发酸，脸上的痕也没有消失，没人能把过去真正擦成空白。可一个人不必等所有伤都消失才配过安静日子。你终于学会把平常当作值得守的东西，不因它不够壮烈，就以为这一生最后非得再换一次震动天下的结尾。", "options": [{"label": "起身把早饭做好，让今日先有烟火", "effects": {"家": 2, "义": 1}, "feedback": "你把火生稳，洗净碗，又给晚起的人留出热水。没有谁为此唱赞歌，你却能从这件小事里确认，自己的手仍能带来不止杀伐的改变。"}, {"label": "慢慢练一趟枪，然后认真休息", "effects": {"忍": 2, "势": 1}, "feedback": "枪法不再为了赢过谁，也不是逼自己证明尚未老去。你练到身体暖起来便停，终于肯让一身本领为自己服务，而非把自己永远交给它驱使。"}]}, {"ch": 31, "title": "人们问起林教头", "text": "偶有客人来问你当年事，有人只想听火场反击，有人想知道谁负了谁，还有少年问若再来一回是否会更早动手。你想了很久，答真正该早的也许不只一拳，还包括听见妻子害怕时不替恶人找理由，听见朋友示警时肯承认自己不能独挡，把退路、证物与可信的人在尚有余裕时连起来。人不必每次都等到忍无可忍，才获得决定自己日子的资格。", "options": [{"label": "讲清选择与条件，不只留下痛快的一夜", "effects": {"证": 2, "家": 1}, "feedback": "你把没来得及做的也说出来，没有拿遗憾装饰英雄。少年听完安静很久，带走的不止一段热血，还多了一点能在现实中照顾人的警觉。"}, {"label": "只向可信者留记录，把日常还给自己", "effects": {"忍": 2, "路": 1}, "feedback": "你拒了几场想借你名字热闹的酒，留下一份朴素记录。既不替加害者掩饰，也不再必须日日重讲伤处，好证明过去确实发生过。"}]}, {"ch": 31, "title": "故人也会老", "text": "接下来的年月没有永远不散的宴，故友终会生病，季节终会替换，有些人走在你前面，有些人晚些。你不再把自然的老去，同当年被阴谋夺走的人命混成一笔无法分清的账。能活到白发已来、能把告别说完、能知道后来人有饭吃，这些并不抵消年轻时的苦，却是那些苦也无权剥夺你的另一部分生活。你整理旧信时把每封都按来日放好，不需要它们再替谁证明一生只有一种颜色。", "options": [{"label": "把旧物交给愿意记住的人，并交代清楚来历", "effects": {"家": 2, "证": 1}, "feedback": "物件终于不再只是逃路时必须贴身护着的东西，也能被安稳地放在一只寻常木匣。接过的人知道哪件属于谁，不必让所有女性与故友都隐去姓名。"}, {"label": "留下该留的，其余随自己安静收起", "effects": {"忍": 2, "义": 1}, "feedback": "你没有命令后人必须继承全部悲愤，只请他们珍惜能自由选择的日子。记忆仍在，却不再被当作下一代必须继续背负的军令。"}]}, {"ch": 31, "title": "这一生你愿归哪里", "text": "最后回看，东京、野猪林、草料场、梁山与江南，并不是一条注定非走不可的线。你曾误信，曾退让，也曾伸手救人与承担，许多结果由此向不同方向分开。不能挽回的不会因一句圆满被抹平，真正护住的也不必被悲剧名声盖过。如今可走的归处都已摆在眼前，它们只承认你一路确实留下的准备与关系，不接受临到结束才补写的保证。你把枪平放，等着给这段人生一个亲自认可的句点。", "options": [{"label": "按一路所行，选择最终归宿", "effects": {"终章": 1}, "feedback": "你终于不必再等待上官、寨主或旁人的评语替自己落笔。接下来能选的结局来自此前的准备，故事将在这里完整结束。"}, {"label": "先重看这一生的家书与抉择，再落笔", "effects": {"回看": 1}, "feedback": "你把重要节点又读一遍，承认遗憾，也认出已经做到的事。看完后仍由你选择可达的归宿，不用为了一个评价把人生再交回别人手中。"}]}];